export function HomePage({ view, goLocal, favorites }: { view: EquiDataRuntime; goLocal: GoLocal; favorites: FavoritesApi }) {
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const [activeModule,setActiveModule]=useState<"lineage"|"genome"|"performance"|"market">("lineage");
  const snapshot = useAsyncValue(async (signal) => {
    const [featured, analytics, quality] = await Promise.all([
      view.platform.registry.browse({ sort: "year", dir: "desc", limit: 6 }, { signal }),
      view.capabilities.analytics ? view.platform.analytics.registry({ signal }).catch(()=>null) : Promise.resolve(null),
      view.capabilities.quality ? view.platform.quality.summary({ signal }).catch(()=>null) : Promise.resolve(null),
    ]);
    return { featured, analytics, quality };
  }, [view.platform, view.capabilities.analytics, view.capabilities.quality]);
  const meta=view.platformMeta;
  return <main className="edx-home-main">
    <section className="edx-hero" id="edx-home">
      <div className="edx-hero-grid" aria-hidden="true"/><div className="edx-hero-glow" aria-hidden="true"/>
      <div className="edx-hero-art-copy">
        <div className="edx-hero-art" aria-hidden="true"><i/><img src="/assets/frontends/equidata-elite/hero-mane.webp" alt=""/></div>
        <div className="edx-hero-copy">
          <Eyebrow>{L("EVIDENCE-DRIVEN BLOODSTOCK INTELLIGENCE","هوشمندی تبار و پرورش مبتنی بر شواهد")}</Eyebrow>
          <h1>{L("DECODE THE","رمزگشایی از")}<br/><span>{L("REGISTRY.","سامانه ثبت.")}</span></h1>
          <p>{L(
            `Explore ${num(meta?.stats.horses,view.locale)} horse records, follow family lines, and compare pedigrees and reviewed breeding evidence in one workspace.`,
            `در میان ${num(meta?.stats.horses,view.locale)} رکورد اسب جست‌وجو کنید، تبارها را دنبال کنید و تبارنامه‌ها و شواهد بررسی‌شدهٔ جفت‌گیری را در یک محیط مقایسه کنید.`
          )}</p>
          <div className="edx-hero-actions"><button className="edx-button primary" onClick={()=>view.navigate(horseDbRoutes.browse())}>{L("BROWSE REGISTRY","کاوش سامانه ثبت")} <Icon name="arrow"/></button><button className="edx-button secondary" onClick={()=>goLocal("/breeding-lab")}>{L("OPEN BREEDING LAB","آزمایشگاه جفت‌گیری")}</button></div>
          <RegistryPulse horseCount={meta?.stats.horses} peopleCount={meta?.stats.people} analyticsReady={view.health?.analyticsReady}/>
        </div>
      </div>
      <RegistryHologramCard view={view}/>
    </section>
    <SignalTicker view={view}/>
    <TruthStatsStrip view={view} analytics={snapshot.data?.analytics??null} quality={snapshot.data?.quality??null}/>
    <section className="edx-content edx-home-content">
      <div className="edx-capability-strip">
        <CapabilityPill available={view.capabilities.pedigreeMetrics} label={L("Pedigree intelligence","تحلیل تبارنامه")}/><CapabilityPill available={view.capabilities.breeding} label={L("Pairing analysis","تحلیل جفت‌گیری")}/><CapabilityPill available={view.capabilities.analytics} label={L("Registry analytics","تحلیل سامانه ثبت")}/><CapabilityPill available={view.capabilities.genomics} label={L("Genomics","ژنومیک")}/><CapabilityPill available={view.capabilities.performance} label={L("Performance","عملکرد")}/><CapabilityPill available={view.capabilities.market} label={L("Market data","داده بازار")}/><CapabilityPill available={view.capabilities.ai} label={L("AI service","سرویس هوش مصنوعی")}/>
      </div>
      <CoreModuleShowcase active={activeModule} onSelect={setActiveModule} view={view} analytics={snapshot.data?.analytics??null} goLocal={goLocal}/>
      <SectionTitle eyebrow={L("INTERACTIVE TOOLS","ابزارهای تعاملی")} title={<>{L("Explore the platform,","پلتفرم را")} <span>{L("hands-on.","عملی کاوش کنید.")}</span></>} copy={L("Find records, trace ancestry, compare horses and review breeding evidence using the tools below.","با ابزارهای زیر رکوردها را پیدا کنید، تبارها را دنبال کنید، اسب‌ها را مقایسه کنید و شواهد جفت‌گیری را بررسی کنید.")}/>
      <div className="edx-module-grid">
        <ModuleCard icon="search" title={L("Registry Explorer","کاوشگر سامانه ثبت")} status="LIVE" copy={L("Canonical search, filters, facets and server-side pagination.","جست‌وجوی مرجع، فیلترها، دسته‌بندی‌ها و صفحه‌بندی سمت سرور.")} onClick={()=>view.navigate(horseDbRoutes.browse())}/>
        <ModuleCard icon="tree" title={L("Pedigree Intelligence","تحلیل تبارنامه")} status={view.capabilities.pedigree?"LIVE":"DORMANT"} copy={L("Ancestor and descendant maps, completeness, repeated ancestors, COI and lineage paths.","نقشه نیاکان و نوادگان، پوشش، نیاکان تکرارشونده، ضریب هم‌خونی و مسیرهای تبار.")} onClick={()=>goLocal("/pedigree/1")}/>
        <ModuleCard icon="compare" title={L("Bloodline Compare","مقایسه تبارها")} status="LIVE" copy={L("Compare canonical records and pedigree metrics with pairwise relationship analysis.","مقایسه رکوردهای مرجع و شاخص‌های تبارنامه همراه با تحلیل خویشاوندی دوتایی.")} onClick={()=>goLocal("/compare")}/>
        <ModuleCard icon="rank" title={L("Registry Rankings","رتبه‌بندی سامانه ثبت")} status={view.capabilities.analytics?"LIVE":"DORMANT"} copy={L("Real rankings from progeny, represented ancestry and people networks—not invented scores.","رتبه‌بندی واقعی بر پایه فرزندان ثبت‌شده، حضور نیاکان و شبکه افراد؛ نه امتیازهای ساختگی.")} onClick={()=>goLocal("/rankings")}/>
        <ModuleCard icon="lab" title={L("Breeding Lab","آزمایشگاه جفت‌گیری")} status={view.capabilities.breeding?"LIVE":"DORMANT"} copy={L("Prospective offspring pedigree COI from parental kinship, with coverage and integrity context.","برآورد ضریب هم‌خونی تبارنامه‌ای فرزند احتمالی از خویشاوندی والدین، همراه با پوشش و یکپارچگی.")} onClick={()=>goLocal("/breeding-lab")}/>
        <ModuleCard icon="ai" title={L("AI Research Assistant","دستیار پژوهشی هوش مصنوعی")} status={view.capabilities.ai?"LIVE":"DORMANT"} copy={view.capabilities.ai?L("Live canonical assistant for grounded registry, pedigree, analytics, and published-content research.","دستیار مرجع فعال برای پژوهش مستند در سامانه ثبت، تبارنامه، تحلیل‌ها و محتوای منتشرشده."):L("Unavailable until the deployment enables the canonical AI service; no fake answers are presented as registry intelligence.","تا فعال‌شدن سرویس مرجع هوش مصنوعی در این استقرار در دسترس نیست؛ پاسخ ساختگی به‌عنوان تحلیل سامانه ثبت نمایش داده نمی‌شود.")} onClick={()=>goLocal("/assistant")}/>
      </div>
      <ScienceTruthSection view={view} analytics={snapshot.data?.analytics??null}/>
      <SectionTitle eyebrow={L("LATEST RECORDS","جدیدترین رکوردها")} title={L("Recently foaled registry records","رکوردهای تازه‌تولد ثبت‌شده")} action={<button className="edx-link-button" onClick={()=>view.navigate(horseDbRoutes.browse())}>{L("VIEW ALL","نمایش همه")} <Icon name="arrow"/></button>}/>
      {snapshot.status==="loading"&&!snapshot.data?<LoadingPanel/>:snapshot.status==="error"?<ErrorPanel error={snapshot.error||L("Unable to load registry","بارگذاری سامانه ثبت ممکن نشد")}/>:snapshot.data?.featured.rows.length?<div className="edx-card-grid">{snapshot.data.featured.rows.map(h=><HorseCard key={h.id} horse={h} runtime={view} favorite={favorites.has(h.id)} onFavorite={()=>favorites.toggle(h.id)} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>)}</div>:<EmptyPanel title={L("No records","رکوردی نیست")} copy={L("The registry returned no featured records.","سامانه ثبت رکورد شاخصی برنگرداند.")}/>}
      {snapshot.data?.analytics&&<AnalyticsHighlights analytics={snapshot.data.analytics} view={view} goLocal={goLocal}/>}
    </section>
  </main>;
}

function RegistryHologramCard({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa); const meta=view.platformMeta; const feature=meta?.featureCatalog;
  const markers=[
    {className:"mark-a",label:L("PEDIGREE","تبارنامه"),sub:feature?.pedigree_metrics?.available?`${L("ENGINE","موتور")} ${feature.pedigree_metrics.version}`:edxStatus(view.locale,false)},
    {className:"mark-b",label:L("PAIRING","جفت‌گیری"),sub:feature?.breeding_analysis?.available?`${L("ENGINE","موتور")} ${feature.breeding_analysis.version}`:edxStatus(view.locale,false)},
    {className:"mark-c",label:L("ANALYTICS","تحلیل"),sub:view.health?.analyticsReady?L("SNAPSHOT READY","تصویر آماری آماده"):L("SNAPSHOT WARMING","در حال آماده‌سازی")},
    {className:"mark-d",label:L("GENOMICS","ژنومیک"),sub:view.capabilities.genomics?L("CONNECTED","متصل"):L("PRESERVED · OFF","حفظ‌شده · خاموش")},
  ];
  return <div className="edx-hero-console"><div className="edx-scanline" aria-hidden="true"/><i className="edx-corner tl"/><i className="edx-corner tr"/><i className="edx-corner bl"/><i className="edx-corner br"/><header><span>{L("REGISTRY NODE · HORSE DB","گره سامانه ثبت · HORSE DB")}</span><b><i/>{L("LIVE DATA","داده زنده")}</b></header><div className="edx-hologram-stage"><div className="edx-holo-ring one"/><div className="edx-holo-ring two"/><img src="/assets/frontends/equidata-elite/hologram-horse.webp" alt=""/>{markers.map(m=><div key={m.label} className={`edx-holo-marker ${m.className}`}><i/><span><b>{m.label}</b><small>{m.sub}</small></span></div>)}</div><footer><strong>{num(meta?.stats.horses,view.locale)}</strong><span>{L("CANONICAL HORSE RECORDS","رکورد مرجع اسب")}</span><button onClick={()=>view.navigate(horseDbRoutes.stats())}>{L("OPEN OBSERVATORY","باز کردن رصدخانه")} <Icon name="arrow"/></button></footer></div>;
}

function SignalTicker({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const items=[L("CANONICAL REGISTRY","سامانه ثبت مرجع"),L("PEDIGREE INTELLIGENCE","تحلیل تبارنامه"),L("RELATIONSHIP ENGINE","موتور خویشاوندی"),L("BREEDING ANALYSIS","تحلیل جفت‌گیری"),L("REGISTRY ANALYTICS","تحلیل سامانه ثبت"),L("DATA QUALITY","کیفیت داده"),`${L("GENOMICS","ژنومیک")} · ${edxStatus(view.locale,view.capabilities.genomics)}`,`${L("PERFORMANCE","عملکرد")} · ${edxStatus(view.locale,view.capabilities.performance)}`,`${L("MARKET","بازار")} · ${edxStatus(view.locale,view.capabilities.market)}`,`${L("AI","هوش مصنوعی")} · ${edxStatus(view.locale,view.capabilities.ai)}`];
  return <div className="edx-ticker"><div>{[...items,...items].map((item,i)=><span key={`${item}-${i}`}>{item}<i/></span>)}</div></div>;
}

function TruthStatsStrip({view,analytics,quality}:{view:EquiDataRuntime;analytics:RegistryAnalyticsResponse|null;quality:{openIssues:number}|null}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa); const depth6=analytics?.pedigree.completeness.find(x=>x.depth===6); const meta=view.platformMeta;
  const stats=[[num(meta?.stats.horses,view.locale),L("CANONICAL HORSES","اسب مرجع")],[num(meta?.stats.people,view.locale),L("PEOPLE ENTITIES","هویت فردی")],[depth6?pct(depth6.averagePercent):"—",L("6-GEN AVG COVERAGE","میانگین پوشش ۶ نسل")],[quality?num(quality.openIssues,view.locale):"—",L("OPEN QUALITY FINDINGS","یافته کیفیت باز")]];
  return <section className="edx-truth-stats" aria-label={L("Live Horse DB statistics","آمار زنده Horse DB")}>{stats.map(([value,label])=><div key={label}><strong>{value}</strong><span>{label}</span></div>)}</section>;
}

function CoreModuleShowcase({active,onSelect,view,analytics,goLocal}:{active:"lineage"|"genome"|"performance"|"market";onSelect:(v:"lineage"|"genome"|"performance"|"market")=>void;view:EquiDataRuntime;analytics:RegistryAnalyticsResponse|null;goLocal:GoLocal}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa); const d6=analytics?.pedigree.completeness.find(x=>x.depth===6);
  const data={
    lineage:{tag:L("03 · LINEAGE","۰۳ · تبار"),tab:L("LINEAGE","تبار"),title:L("Pedigree Intelligence & Relationship Graph","تحلیل تبارنامه و نمودار خویشاوندی"),description:L("Trace recorded ancestry, descendants, repeated ancestors, pedigree completeness, finite-depth coefficients and pairwise relationships with explicit integrity assumptions.","نیاکان، نوادگان، نیاکان تکرارشونده، کامل‌بودن تبارنامه، ضرایب با عمق محدود و خویشاوندی دوتایی را با فرض‌های یکپارچگی شفاف دنبال کنید."),image:"/assets/frontends/equidata-elite/lineage-horse.webp",live:view.capabilities.pedigree,metrics:[[d6?pct(d6.averagePercent):"—",L("6-GEN COVERAGE","پوشش ۶ نسل")],[num(analytics?.pedigree.analyticsEligibleHorseCount,view.locale),L("ANALYSIS-ELIGIBLE","قابل تحلیل")],[num(analytics?.pedigree.cycleContaminatedHorseCount,view.locale),L("CYCLE-AFFECTED","دارای چرخه")]]},
    genome:{tag:L("01 · GENOME","۰۱ · ژنوم"),tab:L("GENOME","ژنوم"),title:L("Full-Spectrum Genomics","ژنومیک جامع"),description:L("The original genomic workspace is preserved intact, but Horse DB currently has no canonical genomic marker dataset. It remains dormant rather than showing simulated markers as fact.","فضای ژنومیک اصلی کاملاً حفظ شده، اما Horse DB هنوز مجموعه مرجع نشانگرهای ژنومی ندارد؛ بنابراین به‌جای نمایش داده شبیه‌سازی‌شده غیرفعال می‌ماند."),image:"/assets/frontends/equidata-elite/genome-closeup.webp",live:view.capabilities.genomics,metrics:[[edxStatus(view.locale,false),L("DATA SOURCE","منبع داده")],[L("PRESERVED","حفظ‌شده"),L("ORIGINAL UI","رابط اصلی")],[L("NO DATASET","بدون مجموعه داده"),L("BACKEND STATUS","وضعیت سرویس")]]},
    performance:{tag:L("02 · PERFORMANCE","۰۲ · عملکرد"),tab:L("PERFORMANCE","عملکرد"),title:L("Performance & Biometric Telemetry","عملکرد و تله‌متری زیستی"),description:L("Federation-recorded competition results are live on every horse profile's RECORDS tab, with per-row provenance. Biometric telemetry, speed indices and soundness feeds remain out of scope — no simulated telemetry is shown.","نتایج مسابقات ثبت‌شدهٔ فدراسیون در تب رکوردهای پروفایل هر اسب با منشأ هر ردیف فعال است. تله‌متری زیستی، شاخص سرعت و سلامت حرکتی خارج از دامنه است؛ هیچ تله‌متری ساختگی نمایش داده نمی‌شود."),image:"/assets/frontends/equidata-elite/performance-horse.webp",live:view.capabilities.performance,metrics:[[edxStatus(view.locale,view.capabilities.performance),L("COMPETITION RECORDS","سوابق مسابقات")],[L("RECORDS TAB","تب رکوردها"),L("HORSE PROFILES","پروفایل اسب")],[L("NO TELEMETRY","بدون تله‌متری"),L("HONEST SCOPE","دامنه صادقانه")]]},
    market:{tag:L("04 · MARKET","۰۴ · بازار"),tab:L("MARKET","بازار"),title:L("Bloodstock Market Intelligence","هوشمندی بازار اسب"),description:L("Canonical marketplace listings are live — hidden prices stay hidden and inquiries are authenticated. Auction history, valuations and price movement remain out of scope; nothing here is a valuation.","آگهی‌های فروش مرجع فعال‌اند — قیمت‌های پنهان پنهان می‌مانند و استعلام‌ها احراز هویت می‌شوند. تاریخچه حراج، ارزش‌گذاری و روند قیمت خارج از دامنه است؛ هیچ‌چیز اینجا ارزش‌گذاری نیست."),image:"/assets/frontends/equidata-elite/market-horse.webp",live:view.capabilities.market,metrics:[[edxStatus(view.locale,view.capabilities.market),L("MARKETPLACE","بازار")],[L("LISTINGS + INQUIRY","آگهی + استعلام"),L("NATIVE PAGES","صفحات بومی")],[L("NO VALUATIONS","بدون ارزش‌گذاری"),L("HONEST SCOPE","دامنه صادقانه")]]},
  } as const;
  const current=data[active];
  return <section className="edx-core-modules" id="edx-modules"><SectionTitle eyebrow={L("CORE MODULES","ماژول‌های اصلی")} title={L("One platform, four disciplines","یک پلتفرم، چهار حوزه")}/><div className="edx-module-tabs" role="tablist" aria-label={L("EquiData disciplines","حوزه‌های EquiData")}>{(["genome","performance","lineage","market"] as const).map(key=><button key={key} role="tab" aria-selected={active===key} className={active===key?"active":""} onClick={()=>onSelect(key)}><span>{data[key].tab}</span><i className={data[key].live?"live":"dormant"}/></button>)}</div><div className={`edx-module-showcase ${current.live?"live":"dormant"}`}><div className="edx-module-image"><img src={current.image} alt=""/><i/></div><div className="edx-module-copy"><span className="edx-module-tag">{current.tag} · {edxStatus(view.locale,current.live)}</span><h3>{current.title}</h3><p>{current.description}</p><dl>{(current.metrics as readonly (readonly [string,string])[]).map(([value,label])=><div key={label}><dd>{value}</dd><dt>{label}</dt></div>)}</dl>{active==="lineage"&&current.live?<button className="edx-module-cta" onClick={()=>goLocal("/pedigree/1")}>{L("OPEN PEDIGREE EXPLORER","باز کردن کاوشگر تبارنامه")} <Icon name="arrow"/></button>:active==="market"&&current.live?<button className="edx-module-cta" onClick={()=>goLocal("/market")}>{L("OPEN MARKETPLACE","باز کردن بازار")} <Icon name="arrow"/></button>:active==="performance"&&current.live?<button className="edx-module-cta" onClick={()=>view.navigate(horseDbRoutes.horse(1))}>{L("OPEN HORSE RECORDS","باز کردن رکوردهای اسب")} <Icon name="arrow"/></button>:<button className="edx-module-cta" disabled>{L("CAPABILITY NOT CONNECTED","قابلیت متصل نیست")}</button>}</div></div></section>;
}

function ScienceTruthSection({view,analytics}:{view:EquiDataRuntime;analytics:RegistryAnalyticsResponse|null}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const points=[
    [L("FINITE-DEPTH PEDIGREE MATH","محاسبات تبارنامه با عمق محدود"),L("Coefficients are derived from recorded ancestry with explicit depth, coverage and founder-boundary assumptions.","ضرایب از نیاکان ثبت‌شده با عمق، پوشش و فرض مرز بنیان‌گذار مشخص محاسبه می‌شوند.")],
    [L("INTEGRITY-AWARE ANALYSIS","تحلیل آگاه از یکپارچگی"),L(`${num(analytics?.pedigree.cycleContaminatedHorseCount,view.locale)} pedigrees currently reach detected cycles; coefficient outputs are suppressed when integrity is unsafe.`,`${num(analytics?.pedigree.cycleContaminatedHorseCount,view.locale)} تبارنامه به چرخه شناسایی‌شده می‌رسند؛ هرجا یکپارچگی ایمن نباشد ضرایب نمایش داده نمی‌شوند.`)],
    [L("NO GENOMIC PRETENSE","بدون ادعای ژنومی"),L("Pedigree COI, relationship and pairing outputs are clearly distinguished from genomic measurements or health/performance predictions.","ضریب هم‌خونی تبارنامه، خویشاوندی و تحلیل جفت‌گیری به‌روشنی از اندازه‌گیری ژنومی یا پیش‌بینی سلامت و عملکرد جدا هستند.")],
  ];
  return <section className="edx-science-truth"><div><Eyebrow>{L("THE SCIENCE","مبنای علمی")}</Eyebrow><h2>{L("Evidence first.","اول شواهد.")} <span>{L("Assumptions exposed.","فرض‌ها شفاف.")}</span></h2><p>{L("EquiData's scientific aesthetic presents only analyses Horse DB can defend, while preserving unsupported scientific modules for future datasets.","زبان علمی EquiData فقط تحلیل‌هایی را نمایش می‌دهد که Horse DB می‌تواند از آن‌ها دفاع کند و ماژول‌های بدون داده را برای آینده حفظ می‌کند.")}</p><div className="edx-science-points">{points.map(([title,copy],i)=><article key={title}><span>{num(i+1,view.locale)}</span><div><strong>{title}</strong><p>{copy}</p></div></article>)}</div></div><div className="edx-science-visual"><img src="/assets/frontends/equidata-elite/dashboard-mockup.webp" alt=""/><i className="edx-scanline"/><span>{L("CANONICAL DATA · CONTRACT","داده مرجع · قرارداد")} {view.platformMeta?.contractVersion||view.platform.contractVersion}</span></div></section>;
}

function ModuleCard({icon,title,status,copy,onClick}:{icon:Parameters<typeof Icon>[0]["name"];title:string;status:"LIVE"|"DORMANT";copy:string;onClick:()=>void}){const locale=typeof document!=="undefined"&&document.documentElement.lang==="fa"?"fa":"en";return <button className={`edx-module-card ${status.toLowerCase()}`} onClick={onClick}><div className="edx-module-icon"><Icon name={icon}/></div><span className="edx-module-status"><i/>{edxStatus(locale,status==="LIVE")}</span><h3>{title}</h3><p>{copy}</p><span className="edx-module-open">{edxText(locale,"OPEN MODULE","باز کردن ماژول")} <Icon name="arrow"/></span></button>}

function AnalyticsHighlights({analytics,view,goLocal}:{analytics:RegistryAnalyticsResponse;view:EquiDataRuntime;goLocal:GoLocal}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const depth6=analytics.pedigree.completeness.find(x=>x.depth===6);return <section className="edx-analytics-highlight"><SectionTitle eyebrow={L("REGISTRY SIGNAL","سیگنال سامانه ثبت")} title={L("Population intelligence, not decorative telemetry","هوشمندی جمعیت، نه تله‌متری تزئینی")} action={<button className="edx-button ghost" onClick={()=>view.navigate(horseDbRoutes.stats())}>{L("FULL OBSERVATORY","مشاهده رصدخانه کامل")}</button>}/><div className="edx-metrics-grid"><Metric label={L("Canonical horses","اسب‌های مرجع")} value={num(analytics.horseCount,view.locale)} tone="cyan"/><Metric label={L("People network","شبکه افراد مرتبط")} value={num(analytics.people?.peopleCount,view.locale)} tone="gold"/><Metric label={L("6-gen average coverage","میانگین پوشش ۶ نسل")} value={pct(depth6?.averagePercent)} tone="green"/><Metric label={L("Cycle-contaminated pedigrees","تبارنامه‌های دارای چرخه")} value={num(analytics.pedigree.cycleContaminatedHorseCount,view.locale)} tone="rose"/></div><div className="edx-topline"><span>{L("Top recorded sire","پدر برتر ثبت‌شده")}</span><strong dir="auto">{analytics.progeny.topSires[0]?horseName({id:analytics.progeny.topSires[0].id,name_latin:analytics.progeny.topSires[0].name_latin||"",name_native:analytics.progeny.topSires[0].name_native},view.locale):"—"}</strong><span>{num(analytics.progeny.topSires[0]?.count,view.locale)} {L("recorded offspring","فرزند ثبت‌شده")}</span><button onClick={()=>goLocal("/rankings")}>{L("Explore rankings","کاوش رتبه‌بندی")}</button></div></section>}


export function RegistryPage({view,favorites}:{view:EquiDataRuntime;favorites:FavoritesApi}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const [query,setQuery]=useState("");
  const [breed,setBreed]=useState("");
  const [sex,setSex]=useState("");
  const [color,setColor]=useState("");
  const [mainStrain,setMainStrain]=useState("");
  const [importedFrom,setImportedFrom]=useState("");
  const [registryFlag,setRegistryFlag]=useState<""|"imported"|"sport"|"stallion"|"sport_card">("");
  const [lifecycle,setLifecycle]=useState("");
  const [advanced,setAdvanced]=useState<AdvancedRegistrySearch>(()=>({...EMPTY_ADVANCED_REGISTRY_SEARCH}));
  const [hasSire,setHasSire]=useState<""|"1"|"0">("");
  const [hasDam,setHasDam]=useState<""|"1"|"0">("");
  const [sort,setSort]=useState<"id"|"name"|"year"|"breed"|"sex"|"place">("id");
  const [dir,setDir]=useState<"asc"|"desc">("asc");
  const [offset,setOffset]=useState(0);
  const limit=24;
  const [favoritesOnly,setFavoritesOnly]=useState(false);
  const [advancedOpen,setAdvancedOpen]=useState(false);
  const [viewMode,setViewMode]=useState<"grid"|"list">(()=>localStorage.getItem("equidata-registry-view")==="list"?"list":"grid");
  const facets=useAsyncValue(signal=>view.capabilities.facets?view.platform.registry.facets({signal}):Promise.resolve({breeds:[],sexes:[],places:[],colors:[],mainStrains:[],importedFrom:[],decades:[],lifecycle:[],flags:[]}),[view.platform,view.capabilities.facets]);
  const registryParams=useMemo<Omit<RegistryBrowseParams,"limit"|"offset">>(()=>({q:query||undefined,breed:breed||undefined,sex:sex||undefined,color:color||undefined,mainStrain:mainStrain||undefined,importedFrom:importedFrom||undefined,isImported:registryFlag==="imported"||undefined,isSport:registryFlag==="sport"||undefined,isStallion:registryFlag==="stallion"||undefined,hasSportCard:registryFlag==="sport_card"||undefined,lifecycle:lifecycle||undefined,...advancedRegistryParams(advanced),hasSire:hasSire===""?undefined:hasSire==="1",hasDam:hasDam===""?undefined:hasDam==="1",sort,dir}),[query,breed,sex,color,mainStrain,importedFrom,registryFlag,lifecycle,advanced,hasSire,hasDam,sort,dir]);
  const csvExport=view.platform.exports.registry(registryParams,"csv");const jsonExport=view.platform.exports.registry(registryParams,"json");
  const results=useAsyncValue(signal=>view.platform.registry.browse({...registryParams,limit,offset},{signal}),[view.platform,registryParams,offset]);
  useEffect(()=>setOffset(0),[query,breed,sex,color,mainStrain,importedFrom,registryFlag,lifecycle,advanced,hasSire,hasDam,sort,dir]);
  useEffect(()=>{localStorage.setItem("equidata-registry-view",viewMode)},[viewMode]);
  const visible=useMemo(()=>favoritesOnly?(results.data?.rows??[]).filter(h=>favorites.has(h.id)):(results.data?.rows??[]),[results.data,favoritesOnly,favorites]);
  const setAdvancedField=(key:keyof AdvancedRegistrySearch,value:string)=>setAdvanced(current=>({...current,[key]:value}));
  const clearAdvanced=()=>{setBreed("");setSex("");setColor("");setMainStrain("");setImportedFrom("");setRegistryFlag("");setLifecycle("");setAdvanced({...EMPTY_ADVANCED_REGISTRY_SEARCH});setHasSire("");setHasDam("");setSort("id");setDir("asc")};
  const advancedActive=Boolean(breed||sex||color||mainStrain||importedFrom||registryFlag||lifecycle||hasAdvancedRegistrySearch(advanced)||hasSire||hasDam||sort!=="id"||dir!=="asc");
  return <main className="edx-content edx-page">
    <SectionTitle headingLevel={1} eyebrow={L("REGISTRY EXPLORER","کاوشگر سامانه ثبت")} title={L("Canonical horse database","پایگاه اصلی ثبت اسب‌ها")} copy={`${num(results.data?.total??view.platformMeta?.stats.horses,view.locale)} ${L("matching records · all filters execute against Horse DB.","رکورد منطبق · همه فیلترها مستقیماً روی پایگاه Horse DB اجرا می‌شوند.")}`}/>
    <div className="edx-registry-toolbar">
      <div className="edx-searchbox large"><Icon name="search"/><input dir="auto" value={query} onChange={e=>setQuery(e.target.value)} placeholder={L("Search name, registry number, owner, breeder, place…","نام، شماره سامانه ثبت، مالک، پرورش‌دهنده، محل تولد…")}/></div>
      <div className="edx-registry-actions">
        <div className="edx-view-switch" role="group" aria-label={L("Registry view","نمایش سامانه ثبت")}><button className={viewMode==="grid"?"active":""} onClick={()=>setViewMode("grid")} aria-pressed={viewMode==="grid"}>▦ {L("CARDS","کارت‌ها")}</button><button className={viewMode==="list"?"active":""} onClick={()=>setViewMode("list")} aria-pressed={viewMode==="list"}>☷ {L("DENSE LIST","فهرست فشرده")}</button></div>
        <button className={`edx-button ${favoritesOnly?"primary":"secondary"}`} onClick={()=>setFavoritesOnly(v=>!v)}><Icon name="star"/> {L("WATCHLIST","پیگیری")} {favorites.count?`(${num(favorites.count,view.locale)})`:""}</button>
        {hasPlatformPermission(view.permissions,"registry.export")&&<div className="edx-export-actions" aria-label={L("Registry export","خروجی سامانه ثبت")}><a className="edx-button ghost" href={csvExport.href} download={csvExport.filename}>⇩ CSV</a><a className="edx-button ghost" href={jsonExport.href} download={jsonExport.filename}>⇩ JSON</a></div>}
        {view.capabilities.structuredSearch&&<button className={`edx-button ghost edx-advanced-toggle${advancedOpen?" active":""}`} aria-expanded={advancedOpen} onClick={()=>setAdvancedOpen(v=>!v)}>{L("ADVANCED","پیشرفته")}{advancedActive?" •":""}</button>}
      </div>
    </div>
    {advancedOpen&&view.capabilities.structuredSearch&&<section className="edx-advanced-filters" aria-label={L("Advanced registry filters","فیلترهای پیشرفته سامانه ثبت")}>
      <label>{L("Breed","نژاد")}<select value={breed} onChange={e=>setBreed(e.target.value)}><option value="">{L("All breeds","همه نژادها")}</option>{facets.data?.breeds.map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Sex","جنسیت")}<select value={sex} onChange={e=>setSex(e.target.value)}><option value="">{L("All sexes","همه جنسیت‌ها")}</option>{facets.data?.sexes.map(x=><option key={x.value} value={x.value}>{edxSexLabel(view.locale,x.value)} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Birth place","محل تولد")}<select value={advanced.place} onChange={e=>setAdvancedField("place",e.target.value)}><option value="">{L("All birth places","همه محل‌های تولد")}</option>{facets.data?.places.map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Color","رنگ")}<select value={color} onChange={e=>setColor(e.target.value)}><option value="">{L("All colors","همه رنگ‌ها")}</option>{facets.data?.colors.map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Main strain","تیره اصلی")}<select value={mainStrain} onChange={e=>setMainStrain(e.target.value)}><option value="">{L("All main strains","همه تیره‌های اصلی")}</option>{facets.data?.mainStrains.map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Sort by","مرتب‌سازی")}<select value={sort} onChange={e=>setSort(e.target.value as typeof sort)}><option value="id">{L("Registry ID","شناسه سامانه ثبت")}</option><option value="name">{L("Name","نام")}</option><option value="year">{L("Birth year","سال تولد")}</option><option value="breed">{L("Breed","نژاد")}</option><option value="sex">{L("Sex","جنسیت")}</option><option value="place">{L("Birth place","محل تولد")}</option></select></label>
      <label>{L("Direction","جهت")}<select value={dir} onChange={e=>setDir(e.target.value as typeof dir)}><option value="asc">{L("Ascending","صعودی")}</option><option value="desc">{L("Descending","نزولی")}</option></select></label>
      <label>{L("Lifecycle","وضعیت")}<select value={lifecycle} onChange={e=>setLifecycle(e.target.value)}><option value="">{L("Any status","همه وضعیت‌ها")}</option>{facets.data?.lifecycle.map(x=><option key={x.value} value={x.value}>{edxLifecycleLabel(view.locale,x.value)} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Import origin","مبدأ واردات")}<select value={importedFrom} onChange={e=>setImportedFrom(e.target.value)}><option value="">{L("Any origin","همه مبدأها")}</option>{facets.data?.importedFrom.map(x=><option key={x.value} value={x.value}>{x.value} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Registry flag","نشانگر ثبت")}<select value={registryFlag} onChange={e=>setRegistryFlag(e.target.value as typeof registryFlag)}><option value="">{L("Any flag","همه نشانگر‌ها")}</option>{facets.data?.flags.map(x=><option key={x.value} value={x.value}>{edxRegistryFlagLabel(view.locale,x.value)} ({num(x.count,view.locale)})</option>)}</select></label>
      <label>{L("Horse name contains","نام اسب")}<input dir="auto" value={advanced.horseName} onChange={e=>setAdvancedField("horseName",e.target.value)}/></label>
      <label>{L("Horse ID","شناسه اسب")}<input inputMode="numeric" value={advanced.horseId} onChange={e=>setAdvancedField("horseId",e.target.value.replace(/[^0-9#]/g,""))}/></label>
      <label>{L("Registration contains","شماره ثبت")}<input dir="auto" value={advanced.registerNo} onChange={e=>setAdvancedField("registerNo",e.target.value)}/></label>
      <label>{L("Birth year from","سال تولد از")}<input inputMode="numeric" value={advanced.yearFrom} onChange={e=>setAdvancedField("yearFrom",e.target.value.replace(/[^0-9]/g,""))}/></label>
      <label>{L("Birth year to","سال تولد تا")}<input inputMode="numeric" value={advanced.yearTo} onChange={e=>setAdvancedField("yearTo",e.target.value.replace(/[^0-9]/g,""))}/></label>
      <label>{L("Owner contains","نام مالک")}<input dir="auto" value={advanced.owner} onChange={e=>setAdvancedField("owner",e.target.value)}/></label>
      <label>{L("Breeder contains","نام پرورش‌دهنده")}<input dir="auto" value={advanced.breeder} onChange={e=>setAdvancedField("breeder",e.target.value)}/></label>
      <label>{L("Importer contains","نام واردکننده")}<input dir="auto" value={advanced.importer} onChange={e=>setAdvancedField("importer",e.target.value)}/></label>
      <label>{L("Passport receiver contains","نام گیرنده گذرنامه")}<input dir="auto" value={advanced.passportReceiver} onChange={e=>setAdvancedField("passportReceiver",e.target.value)}/></label>
      <label>{L("Sire contains","نام پدر")}<input dir="auto" value={advanced.sire} onChange={e=>setAdvancedField("sire",e.target.value)}/></label>
      <label>{L("Dam contains","نام مادر")}<input dir="auto" value={advanced.dam} onChange={e=>setAdvancedField("dam",e.target.value)}/></label>
      <div className="edx-bool-filters"><button className={hasSire==="1"?"active":""} onClick={()=>setHasSire(v=>v==="1"?"":"1")}>{L("Has sire","دارای پدر")}</button><button className={hasDam==="1"?"active":""} onClick={()=>setHasDam(v=>v==="1"?"":"1")}>{L("Has dam","دارای مادر")}</button><button className={hasSire==="0"?"active":""} onClick={()=>setHasSire(v=>v==="0"?"":"0")}>{L("Missing sire","فاقد پدر")}</button><button className={hasDam==="0"?"active":""} onClick={()=>setHasDam(v=>v==="0"?"":"0")}>{L("Missing dam","فاقد مادر")}</button>{advancedActive&&<button onClick={clearAdvanced}>{L("Clear advanced","پاک‌کردن پیشرفته")}</button>}</div>
    </section>}
    {results.status==="loading"&&!results.data?<LoadingPanel label={L("Querying canonical registry…","در حال جست‌وجوی سامانه ثبت مرجع…")}/>:results.status==="error"?<ErrorPanel error={results.error||L("Registry request failed","درخواست سامانه ثبت ناموفق بود")}/>:visible.length?<><div className={viewMode==="list"?"edx-registry-list":"edx-card-grid registry grid"}>{visible.map(h=>viewMode==="list"?<HorseListRow key={h.id} horse={h} runtime={view} favorite={favorites.has(h.id)} onFavorite={()=>favorites.toggle(h.id)} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>:<HorseCard headingLevel={2} key={h.id} horse={h} runtime={view} favorite={favorites.has(h.id)} onFavorite={()=>favorites.toggle(h.id)} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>)}</div><div className="edx-pagination"><button className="edx-button secondary" disabled={offset===0} onClick={()=>setOffset(Math.max(0,offset-limit))}>{view.locale==="fa"?"→":"←"} {L("Previous","قبلی")}</button><span>{num(offset+1,view.locale)}–{num(Math.min(offset+limit,results.data?.total??0),view.locale)} {L("of","از")} {num(results.data?.total,view.locale)}</span><button className="edx-button secondary" disabled={!results.data?.nextOffset} onClick={()=>setOffset(results.data?.nextOffset??offset)}>{L("Next","بعدی")} {view.locale==="fa"?"←":"→"}</button></div></>:<EmptyPanel title={favoritesOnly?L("No watched horses on this page","در این صفحه اسب پیگیری‌شده‌ای نیست"):L("No matching records","رکورد منطبقی پیدا نشد")} copy={favoritesOnly?L("Clear the watchlist filter or add records to your watchlist.","فیلتر پیگیری را خاموش کنید یا رکوردی به فهرست پیگیری بیفزایید."):L("Try broader search terms or clear one of the filters.","عبارت جست‌وجو را عمومی‌تر کنید یا یکی از فیلترها را پاک کنید.")}/>}
  </main>;
}

export function HorseProfilePage({view,id,goLocal,favorites}:{view:EquiDataRuntime;id:number;goLocal:GoLocal;favorites:FavoritesApi}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const profile=useAsyncValue(signal=>view.platform.horses.get(id,{signal}),[view.platform,id]);
  const pedigree=useAsyncValue(async signal=>{
    const insights=view.capabilities.insights?await view.platform.analytics.horseInsights(id,{ancestorDepth:6,descendantDepth:4,metricsDepth:6,coefficientDepth:8},{signal}).catch(()=>null):null;
    const [metrics,coef,desc]=await Promise.all([
      insights?.pedigreeMetrics??(view.capabilities.pedigreeMetrics?view.platform.pedigree.metrics(id,{depth:6},{signal}).catch(()=>null):null),
      insights?.pedigreeCoefficient??(view.capabilities.pedigreeCoefficients?view.platform.pedigree.coefficients(id,{depth:8},{signal}).catch(()=>null):null),
      insights?.descendantMetrics??(view.capabilities.descendantMetrics?view.platform.pedigree.descendantMetrics(id,{depth:4,maxNodes:Math.min(1000,view.platformMeta?.limits.pedigreeDescendantMetricsNodesMax??1000)},{signal}).catch(()=>null):null),
    ]);
    return{metrics,coef,desc,insights};
  },[view.platform,id,view.capabilities.pedigreeMetrics,view.capabilities.pedigreeCoefficients,view.capabilities.descendantMetrics,view.capabilities.insights]);
  const [tab,setTab]=useState<"overview"|"lineage"|"records"|"genome"|"performance"|"market">("overview");
  // R145-C04: the deliberately limited public evidence summary — honest
  // lifecycle counts only (uploaded/reviewed media, attestation states,
  // publicly decided genetics); nothing private is even counted.
  const evidence=useAsyncValue(async signal=>view.capabilities.evidenceSummary?await view.platform.horses.evidenceSummary(id,{signal}).catch(()=>null):null,[view.platform,id,view.capabilities.evidenceSummary]);
  const canClaim=view.capabilities.claims&&Boolean(view.user)&&view.permissions.includes("claim.create");
  if(profile.status==="loading"&&!profile.data)return <main className="edx-content edx-page"><LoadingPanel label={L("Opening registry record…","در حال باز کردن رکورد سامانه ثبت…")}/></main>;
  if(profile.status==="error"||!profile.data)return <main className="edx-content edx-page"><ErrorPanel error={profile.error||L("Horse not found","اسب پیدا نشد")}/></main>;
  const h=profile.data.horse;const adapted=adaptHorse(h,view.locale);const people=profile.data.people;const detail=publicHorseDetailFields(h,{locale:view.locale}).filter(field=>!["register_no","birth_year","birth_place_desc","breed_desc","sex_desc","color_desc","main_strain_desc","sub_strain_desc","is_active","is_dead"].includes(String(field.key)));
  const detailValue=(field:(typeof detail)[number])=>field.kind==="boolean"?(field.value===1?L("Yes","بله"):L("No","خیر")):String(field.value??"—");
  const detailGroups=([
    ["identity",L("Additional identity","هویت تکمیلی")],
    ["registry",L("Registry identifiers","شناسه‌های سامانه ثبت")],
    ["origin",L("Origin & import","مبدأ و واردات")],
    ["lineage",L("Lineage registration","اطلاعات تبار")],
    ["status",L("Registry status flags","وضعیت‌های ثبت")],
  ] as const).map(([group,label])=>({group,label,fields:detail.filter(field=>field.group===group)})).filter(item=>item.fields.length>0);
  const lifecycle=edxLifecycleLabel(view.locale,adapted.lifecycle);
  const dataMode=view.health?.dataMode;const dataModeLabel=dataMode==="client"?L("canonical registry","سامانه ثبت اصلی"):dataMode==="demo"?L("demo dataset","داده آزمایشی"):dataMode==="empty"?L("no data","بدون داده"):L("registry","سامانه ثبت");
  const tabs=[
    ["overview",L("OVERVIEW","نمای کلی")],["lineage",L("LINEAGE","تبارنامه")],["records",L("RECORDS","رکوردها")],["genome",L("GENETIC TESTS","آزمون‌های ژنتیکی")],["performance",L("RESULTS","نتایج")],["market",L("MARKET","بازار")],
  ] as const;
  return <main className="edx-content edx-page"><div className="edx-profile-hero"><HorsePortrait horse={h} runtime={view} size="lg"/><div className="edx-profile-title"><Eyebrow>{L("CANONICAL RECORD","رکورد اصلی سامانه ثبت")} · #{num(h.id,view.locale)}</Eyebrow><h1 dir="auto">{adapted.displayName}</h1>{adapted.secondaryName&&<p dir="auto">{adapted.secondaryName}</p>}<div className="edx-chip-row"><span>{text(h.breed_desc,L("Registry","سامانه ثبت"))}</span><span>{h.sex_desc?edxSexLabel(view.locale,h.sex_desc):L("Sex unknown","جنسیت نامشخص")}</span><span>{text(h.color_desc,L("Color unknown","رنگ نامشخص"))}</span><span>{year(h.birth_year,view.locale)}</span><span className={`status-${adapted.lifecycle}`}>{lifecycle}</span></div></div><div className="edx-profile-actions"><button className={`edx-button ${favorites.has(h.id)?"primary":"secondary"}`} onClick={()=>favorites.toggle(h.id)}>★ {favorites.has(h.id)?L("WATCHING","در پیگیری"):L("WATCHLIST","پیگیری")}</button><button className="edx-button secondary" onClick={()=>goLocal(`/pedigree/${h.id}`)}>{L("PEDIGREE","تبارنامه")}</button>{canClaim&&<a className="edx-button secondary" href="#edx-horse-claim-form">{L("CLAIM","ادعای مالکیت")}</a>}</div></div>
    <EliteHorseClaimPanel view={view} horseId={id}/>
    <div className="edx-profile-kpis"><Metric label={L("Pedigree COI · depth 8","ضریب هم‌خونی تبارنامه · عمق ۸")} value={pct(pedigree.data?.coef?.inbreedingPercent,2,view.locale)} note={L("Pedigree-derived, not genomic","مبتنی بر تبارنامه، نه ژنوم")} tone="cyan"/><Metric label={L("6-gen coverage","پوشش ۶ نسل")} value={pct(pedigree.data?.metrics?.completenessPercent,1,view.locale)} note={`${num(pedigree.data?.metrics?.uniqueAncestors,view.locale)} ${L("unique known ancestors","نیای شناخته‌شده یکتا")}`} tone="gold"/><Metric label={L("Known descendants · depth 4","نوادگان شناخته‌شده · عمق ۴")} value={num(pedigree.data?.desc?.knownDescendants,view.locale)} note={`${num(pedigree.data?.desc?.directChildren,view.locale)} ${L("direct children","فرزند مستقیم")}`} tone="green"/><Metric label={L("Data source","منبع داده")} value={L("CANONICAL","مرجع")} note={dataModeLabel} tone="muted"/></div>
    <ContextNavigation><nav className="edx-tabs" aria-label={L("Horse profile sections","بخش‌های پروفایل اسب")}>{tabs.map(([key,label])=><button key={key} className={tab===key?"active":""} aria-pressed={tab===key} onClick={()=>setTab(key)}>{label}</button>)}</nav></ContextNavigation>
    {tab==="overview"&&<><div className="edx-two-col"><Panel><SectionTitle eyebrow={L("IDENTITY","هویت")} title={L("Registry record","رکورد سامانه ثبت")}/><dl className="edx-data-grid"><Data label={L("Registry number","شماره سامانه ثبت")} value={h.register_no}/><Data label={L("Birth year","سال تولد")} value={year(h.birth_year,view.locale)}/><Data label={L("Birth place","محل تولد")} value={h.birth_place_desc}/><Data label={L("Breed","نژاد")} value={h.breed_desc}/><Data label={L("Sex","جنسیت")} value={h.sex_desc}/><Data label={L("Color","رنگ")} value={h.color_desc}/><Data label={L("Main strain","تیره اصلی")} value={h.main_strain_desc}/><Data label={L("Sub strain","زیرتیره")} value={h.sub_strain_desc}/></dl></Panel><Panel><SectionTitle eyebrow={L("CONNECTIONS","ارتباطات")} title={L("Parents & people","والدین و افراد")}/><dl className="edx-data-grid"><ConnectionData label={L("Sire","پدر")} value={(view.locale==="fa"?h.father_name_native||h.father_name:h.father_name||h.father_name_native)||h.father_id} onOpen={h.father_id?()=>view.navigate(horseDbRoutes.horse(h.father_id!)):undefined}/><ConnectionData label={L("Dam","مادر")} value={(view.locale==="fa"?h.mother_name_native||h.mother_name:h.mother_name||h.mother_name_native)||h.mother_id} onOpen={h.mother_id?()=>view.navigate(horseDbRoutes.horse(h.mother_id!)):undefined}/>{people.map((person,i)=><ConnectionData key={`${person.role}-${person.id}-${i}`} label={person.role==="owner"?L("Owner","مالک"):person.role==="breeder"?L("Breeder","پرورش‌دهنده"):person.role==="importer"?L("Importer","واردکننده"):person.role==="passport_receiver"?L("Passport receiver","گیرنده گذرنامه"):person.role} value={(view.locale==="fa"?person.name_native||person.name_latin:person.name_latin||person.name_native)||`${L("Person","فرد")} #${num(person.id,view.locale)}`} onOpen={()=>view.navigate(horseDbRoutes.person(person.id))}/>)}</dl></Panel></div>{evidence.data&&<Panel><SectionTitle eyebrow={L("EVIDENCE","شواهد")} title={L("Public evidence summary","خلاصهٔ عمومی شواهد")} copy={L("Reviewed is platform review, never issuer attestation. Private and rejected evidence is not even counted here.","بررسی‌شده یعنی بررسی سامانه، نه تأیید مرجع. شواهد خصوصی و رد‌شده اصلاً شمرده نمی‌شوند.")}/>
      <dl className="edx-data-grid">
        <Data label={L("Uploaded media","رسانه بارگذاری‌شده")} value={String(evidence.data.media.uploaded??0)}/>
        <Data label={L("Platform-reviewed media","رسانه بررسی‌شده توسط سامانه")} value={String(evidence.data.media.reviewed??0)}/>
        <Data label={L("Active attestations","تأییدهای فعال")} value={String(evidence.data.attestations.active??0)}/>
        <Data label={L("Revoked attestations","تأییدهای لغوشده")} value={String(evidence.data.attestations.revoked??0)}/>
        <Data label={L("Superseded attestations","تأییدهای جایگزین‌شده")} value={String(evidence.data.attestations.superseded??0)}/>
        <Data label={L("Published genetic results","نتایج ژنتیکی منتشرشده")} value={String(Object.values(evidence.data.genetics_published).reduce((a,b)=>a+b,0))}/>
      </dl></Panel>}{detail.length>0&&<Panel className="edx-canonical-detail"><SectionTitle eyebrow={L("CANONICAL DETAIL","جزئیات ثبت‌شده")} title={L("Complete public registry fields","اطلاعات کامل عمومی سامانه ثبت")} copy={L("Sensitive source identifiers remain restricted to authorized curation tools.","شناسه‌های حساس منبع فقط در ابزارهای مدیریتیِ مجاز نمایش داده می‌شوند.")}/><div className="edx-detail-groups">{detailGroups.map(group=><section className="edx-detail-group" data-group={group.group} key={group.group}><header><span/><h3>{group.label}</h3><small>{num(group.fields.length,view.locale)} {L("fields","فیلد")}</small></header><dl className="edx-data-grid edx-data-grid-wide">{group.fields.map(field=><Data key={String(field.key)} label={pick(field.label, view.locale)} value={detailValue(field)}/>)}</dl></section>)}</div>{profile.data.aliases?.length?<div className="edx-aliases"><strong>{L("Aliases","نام‌های جایگزین")}</strong>{profile.data.aliases.map(alias=><span key={alias.id} dir="auto">{alias.alias}</span>)}</div>:null}</Panel>}{pedigree.data?.insights?.insights?.length?<InsightsPanel view={view} insights={pedigree.data.insights.insights}/>:null}{pedigree.data?.insights?.premiumPedigree?<EquiDataPremiumHorse view={view} premium={pedigree.data.insights.premiumPedigree}/>:null}{pedigree.data?.insights?.referencePopulation?<EquiDataReferenceHorse view={view} reference={pedigree.data.insights.referencePopulation}/>:null}</>}
    {tab==="lineage"&&<LineagePanel view={view} horse={h} metrics={pedigree.data?.metrics||null} coefficient={pedigree.data?.coef||null} goLocal={goLocal}/>}
    {tab==="records"&&<EquiDataRecordModules view={view} horseId={h.id} goLocal={goLocal}/>}
    {tab==="genome"&&<EquiDataRecordModulesDetails view={view} horseId={h.id} goLocal={goLocal} sectionOnly="genetics"/>}
    {tab==="performance"&&<EquiDataRecordModulesDetails view={view} horseId={h.id} goLocal={goLocal} sectionOnly="competitions"/>}
    {tab==="market"&&<Panel><SectionTitle title={L("Marketplace","بازار")}/><p className="edx-muted">{L("Canonical sales listings live on the marketplace page; hidden prices stay hidden and nothing there is a valuation.","آگهی‌های فروش مرجع در صفحه بازار هستند؛ قیمت‌های پنهان پنهان می‌مانند و هیچ‌چیز ارزش‌گذاری نیست.")}</p><button className="edx-button primary" onClick={()=>goLocal("/market")}>{L("OPEN MARKETPLACE","باز کردن بازار")}</button></Panel>}
  </main>;
}
function Data({label,value}:{label:string;value:unknown}){return <div><dt>{label}</dt><dd dir="auto">{value===null||value===undefined||value===""?"—":String(value)}</dd></div>}
function ConnectionData({label,value,onOpen}:{label:string;value:unknown;onOpen?:()=>void}){return <div><dt>{label}</dt><dd dir="auto">{onOpen?<button className="edx-data-link" onClick={onOpen}>{value===null||value===undefined||value===""?"—":String(value)} <Icon name="arrow"/></button>:value===null||value===undefined||value===""?"—":String(value)}</dd></div>}
function InsightsPanel({view,insights}:{view:EquiDataRuntime;insights:Array<{code:string;importance:string;values:Record<string,string|number|boolean|null>;relatedHorses?:Array<{id:number;name_latin?:string|null;name_native?:string|null;birth_year?:number|null}>;provenance?:{source:string;algorithmVersion:string}}>}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const labels:Record<string,[string,string]>={pedigree_coverage:["Pedigree coverage","پوشش تبارنامه"],branch_imbalance:["Branch imbalance","عدم توازن شاخه‌ها"],repeated_ancestor:["Repeated ancestor","نیای تکرارشونده"],tail_male_line:["Tail-male line","خط پدری مستقیم"],tail_female_line:["Tail-female line","خط مادری مستقیم"],pedigree_inbreeding:["Pedigree inbreeding","هم‌خونی تبارنامه"],descendant_reach:["Descendant reach","گستره نوادگان"],pedigree_integrity_warning:["Pedigree integrity warning","هشدار یکپارچگی تبارنامه"]};
  const valueLabel=(key:string)=>key.replace(/([A-Z])/g," $1").replaceAll("_"," ").replace(/^./,c=>c.toUpperCase());
  return <Panel className="edx-insights"><SectionTitle eyebrow={L("STRUCTURED INSIGHTS","بینش‌های ساختاریافته")} title={L("Horse intelligence","تحلیل اسب")} copy={L("All live insight families, supporting values, related horses and algorithm provenance are preserved here.","همه خانواده‌های بینش زنده، مقادیر پشتیبان، اسب‌های مرتبط و منشأ الگوریتمی در اینجا حفظ می‌شوند.")}/><div className="edx-insight-grid">{insights.map((item,index)=>{const pair=labels[item.code]??[item.code,item.code];return <article key={`${item.code}-${index}`} className={`importance-${item.importance}`}><header><span>{L(pair[0],pair[1])}</span><small>{edxInsightImportanceLabel(view.locale,item.importance)}</small></header><dl>{Object.entries(item.values).map(([key,value])=><div key={key}><dt>{valueLabel(key)}</dt><dd dir="auto">{String(value??"—")}</dd></div>)}</dl>{item.relatedHorses?.length?<div className="edx-insight-horses">{item.relatedHorses.map(horse=><button key={horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(horse.id))} dir="auto"><strong>{horseName({id:horse.id,name_latin:horse.name_latin||"",name_native:horse.name_native},view.locale)}</strong><small>#{num(horse.id,view.locale)}{horse.birth_year?` · ${year(horse.birth_year,view.locale)}`:""}</small></button>)}</div>:null}{item.provenance?<footer>{item.provenance.source} · {item.provenance.algorithmVersion}</footer>:null}</article>})}</div></Panel>
}
function LineagePanel({view,horse,metrics,coefficient,goLocal}:{view:EquiDataRuntime;horse:HorseRecord;metrics:PedigreeMetricsResponse|null;coefficient:PedigreeCoefficientResponse|null;goLocal:GoLocal}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);return <div className="edx-two-col"><Panel><SectionTitle eyebrow={L("PEDIGREE SIGNAL","سیگنال تبارنامه")} title={L("Structural pedigree intelligence","هوشمندی ساختاری تبارنامه")}/><div className="edx-gauge-row"><CoefficientGauge label={L("Pedigree COI","ضریب هم‌خونی تبارنامه")} percentValue={coefficient?.inbreedingPercent} note={`${L("depth","عمق")} ${num(coefficient?.depth??8,view.locale)}`}/><CoefficientGauge label={L("Recorded coverage","پوشش ثبت‌شده")} percentValue={metrics?.completenessPercent} note={`${L("depth","عمق")} ${num(metrics?.depth??6,view.locale)}`}/></div><p className="edx-science-note">{L("Coverage is structural pedigree completeness. COI is a finite-depth pedigree coefficient under the documented founder assumption; neither is a genomic measurement.","پوشش، کامل‌بودن ساختاری تبارنامه است. ضریب هم‌خونی نیز محاسبه تبارنامه‌ای با عمق محدود و فرض بنیان‌گذار مستند است؛ هیچ‌کدام اندازه‌گیری ژنومی نیستند.")}</p><button className="edx-button primary" onClick={()=>goLocal(`/pedigree/${horse.id}`)}>{L("OPEN FULL PEDIGREE","باز کردن تبارنامه کامل")} <Icon name="arrow"/></button></Panel><Panel><SectionTitle eyebrow={L("REPEATED ANCESTORS","نیاکان تکرارشونده")} title={L("Linebreeding structure","ساختار هم‌تباری")}/>{metrics?.topRepeatedAncestors?.length?<div className="edx-rank-list">{metrics.topRepeatedAncestors.map((ancestor,i)=><div key={ancestor.horse.id}><span>#{num(i+1,view.locale)}</span><strong dir="auto">{horseName(ancestor.horse,view.locale)}</strong><small>{num(ancestor.occurrences,view.locale)} {L("appearances","بار تکرار")} · {L("nearest","نزدیک‌ترین")} G{num(ancestor.nearestGeneration,view.locale)}</small></div>)}</div>:<p className="edx-muted">{L("No repeated ancestor leaders were returned at this depth.","در این عمق نیای تکرارشونده شاخصی ثبت نشده است.")}</p>}</Panel></div>}

export function PedigreePage({view,id}:{view:EquiDataRuntime;id:number}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const [mode,setMode]=useState<"ancestors"|"descendants">("ancestors");
  const [visual,setVisual]=useState<"graph"|"radial"|"ledger">("graph");
  const [depth,setDepth]=useState(5);
  const [pathTarget,setPathTarget]=useState<HorseRecord|null>(null);
  const state=useAsyncValue(async signal=>{
    if(mode==="ancestors"&&!view.capabilities.pedigree)throw new Error(L("Pedigree capability unavailable","قابلیت تبارنامه در دسترس نیست"));
    if(mode==="descendants"&&!view.capabilities.descendants)throw new Error(L("Descendant capability unavailable","قابلیت نوادگان در دسترس نیست"));
    const [tree,insights]=await Promise.all([
      mode==="ancestors"?view.platform.pedigree.ancestors(id,{depth},{signal}):view.platform.pedigree.descendants(id,{depth:Math.min(depth,6),maxNodes:900},{signal}),
      view.capabilities.insights?view.platform.analytics.horseInsights(id,{ancestorDepth:Math.min(depth,8),descendantDepth:Math.min(depth,6),metricsDepth:Math.min(depth,8),coefficientDepth:Math.max(8,depth)},{signal}).catch(()=>null):null,
    ]);
    const [metrics,coef,descMetrics]=await Promise.all([
      insights?.pedigreeMetrics??(view.capabilities.pedigreeMetrics?view.platform.pedigree.metrics(id,{depth},{signal}).catch(()=>null):null),
      insights?.pedigreeCoefficient??(view.capabilities.pedigreeCoefficients?view.platform.pedigree.coefficients(id,{depth:Math.max(8,depth)},{signal}).catch(()=>null):null),
      insights?.descendantMetrics??(view.capabilities.descendantMetrics?view.platform.pedigree.descendantMetrics(id,{depth:Math.min(depth,6),maxNodes:Math.min(1000,view.platformMeta?.limits.pedigreeDescendantMetricsNodesMax??1000)},{signal}).catch(()=>null):null),
    ]);
    return{tree,metrics,coef,descMetrics};
  },[view.platform,id,mode,depth,view.capabilities.pedigree,view.capabilities.descendants,view.capabilities.pedigreeMetrics,view.capabilities.pedigreeCoefficients,view.capabilities.descendantMetrics,view.capabilities.insights,view.locale]);
  const paths=useAsyncValue(async signal=>pathTarget&&view.capabilities.pedigreePaths?view.platform.pedigree.pathsToAncestor(id,pathTarget.id,{depth:8,maxPaths:8},{signal}):null,[view.platform,id,pathTarget?.id,view.capabilities.pedigreePaths]);
  const tree=state.data?.tree;
  const truncated=tree&&"truncated" in tree?Boolean(tree.truncated):false;
  return <main className="edx-content edx-page">
    <SectionTitle headingLevel={1} eyebrow={L("PEDIGREE EXPLORER","کاوشگر تبارنامه")} title={`${L("Lineage graph","نمودار تبار")} · #${num(id,view.locale)}`} copy={L("Recorded pedigree positions remain explicit; ancestor, descendant and path views are bounded and integrity-aware.","جایگاه‌های ثبت‌شده تبارنامه به‌صورت صریح حفظ می‌شوند؛ نماهای نیاکان، نوادگان و مسیرها محدود و آگاه از یکپارچگی هستند.")}/>
    <div className="edx-pedigree-toolbar"><div className="edx-pedigree-controls"><div className="edx-view-switch"><button className={mode==="ancestors"?"active":""} onClick={()=>setMode("ancestors")}>{L("ANCESTORS","نیاکان")}</button><button className={mode==="descendants"?"active":""} disabled={!view.capabilities.descendants} onClick={()=>{setMode("descendants");if(visual==="radial")setVisual("graph")}}>{L("DESCENDANTS","نوادگان")}</button></div><div className="edx-view-switch visual"><button className={visual==="graph"?"active":""} onClick={()=>setVisual("graph")}>{L("GRAPH","نمودار")}</button><button className={visual==="radial"?"active":""} disabled={mode!=="ancestors"} onClick={()=>setVisual("radial")}>{L("RADIAL","حلقوی")}</button><button className={visual==="ledger"?"active":""} onClick={()=>setVisual("ledger")}>{L("LEDGER","فهرست")}</button></div><label className="edx-pedigree-depth"><span>{L("GENERATIONS","نسل‌ها")}</span><input type="range" min="2" max="8" value={depth} onChange={e=>setDepth(Number(e.target.value))}/><b>G{num(depth,view.locale)}</b></label></div>{truncated&&<span className="edx-truncated"><Icon name="warn"/> {L("Bounded result · truncated","نتیجه محدود · بریده‌شده")}</span>}</div>
    {state.status==="loading"?<LoadingPanel label={L(mode==="ancestors"?"Tracing ancestor graph…":"Tracing descendant graph…",mode==="ancestors"?"در حال ترسیم نمودار نیاکان…":"در حال ترسیم نمودار نوادگان…")}/>:state.status==="error"||!state.data?<ErrorPanel error={state.error||L("Pedigree unavailable","تبارنامه در دسترس نیست")}/>:<>
      <div className="edx-profile-kpis">{mode==="ancestors"?<><Metric label={L("6-gen coverage","پوشش ۶ نسل")} value={pct(state.data.metrics?.completenessPercent)} tone="cyan"/><Metric label={L("Unique ancestors","نیاکان یکتا")} value={num(state.data.metrics?.uniqueAncestors,view.locale)} tone="gold"/><Metric label={L("Repeated positions","جایگاه‌های تکراری")} value={num(state.data.metrics?.repeatedAncestorPositions,view.locale)} tone="rose"/><Metric label={L("Pedigree COI","ضریب هم‌خونی تبارنامه")} value={pct(state.data.coef?.inbreedingPercent,2)} tone="green"/></>:<><Metric label={L("Direct children","فرزندان مستقیم")} value={num(state.data.descMetrics?.directChildren,view.locale)} tone="cyan"/><Metric label={L("Known descendants","نوادگان شناخته‌شده")} value={num(state.data.descMetrics?.knownDescendants,view.locale)} tone="gold"/><Metric label={L("Max known generation","بیشترین نسل شناخته‌شده")} value={num(state.data.descMetrics?.maxKnownGeneration,view.locale)} tone="green"/><Metric label={L("Traversal","پیمایش")} value={state.data.descMetrics?.truncated?L("TRUNCATED","بریده"):L("BOUNDED","محدود")} tone={state.data.descMetrics?.truncated?"rose":"muted"}/></>}</div>
      <Panel className={`edx-pedigree-panel view-${visual}`}>{visual==="graph"?<PedigreeMap root={state.data.tree.tree} runtime={view} maxGeneration={depth} onOpen={h=>view.navigate(horseDbRoutes.horse(h.id))}/>:visual==="radial"&&mode==="ancestors"?<PedigreeRadial root={state.data.tree.tree} runtime={view} maxGeneration={depth} onOpen={h=>view.navigate(horseDbRoutes.horse(h.id))}/>:<PedigreeLedger root={state.data.tree.tree} runtime={view} maxGeneration={depth} onOpen={h=>view.navigate(horseDbRoutes.horse(h.id))}/>}</Panel>
      {state.data.metrics?.integrity.cycleDetected&&<Panel className="edx-warning"><Icon name="warn"/><strong>{L("Cycle-contaminated pedigree","تبارنامه دارای چرخه")}</strong><p>{L("Scientific coefficients are suppressed where integrity guarantees cannot be met.","هرجا تضمین یکپارچگی برقرار نباشد، ضرایب علمی نمایش داده نمی‌شوند.")}</p></Panel>}
    </>}
    {view.capabilities.pedigreePaths&&<Panel className="edx-path-explorer"><SectionTitle eyebrow={L("ANCESTOR PATHS","مسیرهای نیاکان")} title={L("Trace every recorded route","ردیابی مسیرهای ثبت‌شده")} copy={L("Choose a possible ancestor to enumerate bounded sire/dam routes from the subject.","یک نیای احتمالی را انتخاب کنید تا مسیرهای محدود پدری/مادری از رکورد اصلی فهرست شوند.")}/><HorsePicker platform={view.platform} locale={view.locale} label={L("ANCESTOR TARGET","نیای هدف")} value={pathTarget} onChange={setPathTarget}/>{pathTarget&&paths.status==="loading"?<LoadingPanel label={L("Tracing paths…","در حال ردیابی مسیرها…")}/>:paths.data?<div className="edx-path-list">{paths.data.paths.length?paths.data.paths.map((route,index)=><article key={`${route.path.join("-")}-${index}`} className={route.branch??"neutral"}><header><strong>{L("Path","مسیر")} {num(index+1,view.locale)}</strong><span>{route.branch==="sire"?L("Sire branch","شاخه پدری"):route.branch==="dam"?L("Dam branch","شاخه مادری"):L("Mixed/subject","ترکیبی")}</span></header><div>{route.path.map((horseId,i)=><React.Fragment key={`${horseId}-${i}`}><button onClick={()=>view.navigate(horseDbRoutes.horse(horseId))}>#{num(horseId,view.locale)}</button>{i<route.path.length-1&&<Icon name="arrow"/>}</React.Fragment>)}</div></article>):<EmptyPanel title={L("No recorded path","مسیر ثبت‌شده‌ای نیست")} copy={L("The selected horse was not reached as an ancestor within depth 8.","اسب انتخاب‌شده در عمق ۸ به‌عنوان نیا پیدا نشد.")}/>} {paths.data.truncated&&<p className="edx-science-note">{L("Additional paths exist beyond the configured response bound.","مسیرهای بیشتری فراتر از حد پاسخ تنظیم‌شده وجود دارند.")}</p>}</div>:null}</Panel>}
  </main>;
}

export function ComparePage({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa); const [horses,setHorses]=useState<Array<HorseRecord|null>>([null,null,null,null]);const chosen=horses.filter((h):h is HorseRecord=>Boolean(h));
  const details=useAsyncValue(async signal=>Promise.all(chosen.map(async h=>{const [profile,metrics,coef]=await Promise.all([view.platform.horses.get(h.id,{signal}),view.capabilities.pedigreeMetrics?view.platform.pedigree.metrics(h.id,{depth:6},{signal}).catch(()=>null):null,view.capabilities.pedigreeCoefficients?view.platform.pedigree.coefficients(h.id,{depth:8},{signal}).catch(()=>null):null]);return{horse:profile.horse,metrics,coef}})),[view.platform,chosen.map(h=>h.id).join(","),view.capabilities.pedigreeMetrics,view.capabilities.pedigreeCoefficients]);
  const pair=useAsyncValue(async signal=>chosen.length>=2&&view.capabilities.relationships?Promise.all([view.platform.relationships.commonAncestors(chosen[0].id,chosen[1].id,{depth:8},{signal}),view.capabilities.pedigreeCoefficients?view.platform.relationships.coefficients(chosen[0].id,chosen[1].id,{depth:8},{signal}).catch(()=>null):null]):null,[view.platform,chosen[0]?.id,chosen[1]?.id,view.capabilities.relationships,view.capabilities.pedigreeCoefficients]);
  return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("COMPARE BLOODLINES","مقایسه تبارها")} title={L("Canonical side-by-side analysis","تحلیل مرجع کنارهم")} copy={L("Production comparison uses real identity, pedigree coverage, COI and relationship data. Unsupported genomic/performance/market comparison remains preserved but disabled.","مقایسه فعال از هویت واقعی، پوشش تبارنامه، ضریب هم‌خونی و داده خویشاوندی استفاده می‌کند. مقایسه ژنومی، عملکرد و بازار بدون داده معتبر حفظ اما غیرفعال است.")}/><div className="edx-picker-grid">{horses.map((h,i)=><HorsePicker key={i} platform={view.platform} locale={view.locale} label={`${L("PROFILE","پروفایل")} ${num(i+1,view.locale)}`} value={h} onChange={horse=>setHorses(current=>current.map((x,j)=>j===i?horse:x))}/>)}</div>{details.status==="loading"&&chosen.length?<LoadingPanel label={L("Building comparison…","در حال ساخت مقایسه…")}/>:details.data?.length?<div className="edx-compare-table"><div className="head"><span>{L("Metric","شاخص")}</span>{details.data.map(x=><strong key={x.horse.id} dir="auto">{horseName(x.horse,view.locale)}</strong>)}</div><CompareRow label={L("Registry ID","شناسه سامانه ثبت")} values={details.data.map(x=>`#${num(x.horse.id,view.locale)}`)}/><CompareRow label={L("Birth year","سال تولد")} values={details.data.map(x=>year(x.horse.birth_year,view.locale))}/><CompareRow label={L("Breed","نژاد")} values={details.data.map(x=>text(x.horse.breed_desc))}/><CompareRow label={L("Sex","جنسیت")} values={details.data.map(x=>text(x.horse.sex_desc))}/><CompareRow label={L("Birth place","محل تولد")} values={details.data.map(x=>text(x.horse.birth_place_desc))}/><CompareRow label={L("6-gen pedigree coverage","پوشش تبارنامه ۶ نسل")} values={details.data.map(x=>pct(x.metrics?.completenessPercent))}/><CompareRow label={L("Unique ancestors","نیاکان یکتا")} values={details.data.map(x=>num(x.metrics?.uniqueAncestors,view.locale))}/><CompareRow label={L("Repeated positions","جایگاه‌های تکراری")} values={details.data.map(x=>num(x.metrics?.repeatedAncestorPositions,view.locale))}/><CompareRow label={L("Pedigree COI · depth 8","ضریب هم‌خونی · عمق ۸")} values={details.data.map(x=>pct(x.coef?.inbreedingPercent,2))}/></div>:<EmptyPanel title={L("Select two to four registry horses","دو تا چهار اسب سامانه ثبت انتخاب کنید")} copy={L("Search above to build a real-data comparison.","برای ساخت مقایسه واقعی از جست‌وجوی بالا استفاده کنید.")}/>} {chosen.length>=2&&<RelationshipPanel view={view} a={chosen[0]} b={chosen[1]} state={pair}/>}<div className="edx-dormant-grid"><DormantFeature title={L("Genomic score comparison","مقایسه امتیاز ژنومی")} reason={L("No genomic source is connected.","منبع ژنومی متصل نیست.")}/><DormantFeature title={L("Performance & market comparison","مقایسه عملکرد و بازار")} reason={L("No canonical performance or market dataset is connected.","مجموعه داده مرجع عملکرد یا بازار متصل نیست.")}/></div></main>;
}
function CompareRow({label,values}:{label:string;values:React.ReactNode[]}){return <div className="row"><span>{label}</span>{values.map((v,i)=><b key={i}>{v}</b>)}</div>}
function RelationshipPanel({view,a,b,state}:{view:EquiDataRuntime;a:HorseRecord;b:HorseRecord;state:AsyncState<[RelationshipResponse,RelationshipCoefficientResponse|null]|null>}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  if(!view.capabilities.relationships)return <DormantFeature title={L("Relationship analysis","تحلیل خویشاوندی")} reason={L("The active backend does not expose pairwise relationship analysis.","سرویس فعال تحلیل خویشاوندی دوتایی را ارائه نمی‌کند.")}/>;
  if(state.status==="loading")return <LoadingPanel label={L("Tracing shared ancestry…","در حال ردیابی نیاکان مشترک…")}/>;
  if(!state.data)return null;
  const [rel,coef]=state.data;
  const kind=rel.summary?.kind.replaceAll("_"," ")??L("Recorded shared ancestry","نیاکان مشترک ثبت‌شده");
  return <Panel className="edx-relationship-atlas"><SectionTitle eyebrow={L("PAIRWISE RELATIONSHIP","خویشاوندی دوتایی")} title={<><span dir="auto">{horseName(a,view.locale)}</span> × <span dir="auto">{horseName(b,view.locale)}</span></>} copy={view.locale==="fa"?L("Relationship classification from recorded pedigree","طبقه‌بندی خویشاوندی از تبارنامه ثبت‌شده"):kind}/>
    <div className="edx-metrics-grid"><Metric label={L("Relationship","خویشاوندی")} value={pct(coef?.relationshipPercent,2)} tone="cyan"/><Metric label={L("Kinship","هم‌تباری")} value={pct(coef?.kinshipPercent,2)} tone="gold"/><Metric label={L("Shared ancestors","نیاکان مشترک")} value={num(rel.commonAncestors.length,view.locale)} tone="green"/><Metric label={L("Depth","عمق")} value={num(coef?.depth??8,view.locale)} tone="muted"/></div>
    {rel.commonAncestors.length>0&&<section className="edx-relationship-section"><h3>{L("Shared-ancestor ledger","دفتر نیاکان مشترک")}</h3><div className="edx-common-ancestors">{rel.commonAncestors.map((ancestor,index)=><button key={`${ancestor.horse.id}-${index}`} onClick={()=>view.navigate(horseDbRoutes.horse(ancestor.horse.id))}><strong dir="auto">{horseName(ancestor.horse,view.locale)}</strong><span>#{num(ancestor.horse.id,view.locale)} · {L("from","از")} G{num(ancestor.fromDepth,view.locale)} / {L("to","تا")} G{num(ancestor.toDepth,view.locale)} · ΣG{num(ancestor.totalDepth,view.locale)}</span></button>)}</div></section>}
    {rel.atlas&&<section className="edx-relationship-section"><h3>{L("Relationship path atlas","اطلس مسیرهای خویشاوندی")}</h3><p className="edx-science-note">{localizedAnalysisText(rel.atlas.provenance.interpretation,view.locale)} · {localizedDigits(rel.atlas.provenance.algorithmVersion,view.locale)}</p><div className="edx-path-list">{rel.atlas.connections.map((connection,index)=><article key={`${connection.via.id}-${index}`}><header><strong>{L("Connection","اتصال")} {num(index+1,view.locale)}</strong><span>{L("via ancestor","از طریق نیا")} #{num(connection.via.id,view.locale)}</span></header><div>{connection.fromPath.map((horseId,i)=><React.Fragment key={`a-${horseId}-${i}`}><button onClick={()=>view.navigate(horseDbRoutes.horse(horseId))}>#{num(horseId,view.locale)}</button>{i<connection.fromPath.length-1&&<Icon name="arrow"/>}</React.Fragment>)}<span className="edx-route-join">⇄</span>{connection.toPath.map((horseId,i)=><React.Fragment key={`b-${horseId}-${i}`}><button onClick={()=>view.navigate(horseDbRoutes.horse(horseId))}>#{num(horseId,view.locale)}</button>{i<connection.toPath.length-1&&<Icon name="arrow"/>}</React.Fragment>)}</div></article>)}</div>{rel.atlas.pathEnumerationTruncated&&<p className="edx-science-note">{L("Additional relationship paths exist beyond the platform response bound.","مسیرهای خویشاوندی بیشتری فراتر از حد پاسخ پلتفرم وجود دارد.")}</p>}</section>}
  </Panel>
}

export function RankingsPage({view}:{view:EquiDataRuntime}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const state=useAsyncValue(signal=>view.capabilities.analytics?view.platform.analytics.registry({signal}):Promise.reject(new Error(L("Registry analytics capability unavailable","قابلیت تحلیل سامانه ثبت در دسترس نیست"))),[view.platform,view.capabilities.analytics,view.locale]);if(state.status==="loading")return <main className="edx-content edx-page"><LoadingPanel label={L("Loading registry rankings…","در حال بارگذاری رتبه‌بندی…")}/></main>;if(state.status==="error"||!state.data)return <main className="edx-content edx-page"><DormantFeature title={L("Registry rankings","رتبه‌بندی سامانه ثبت")} reason={state.error||L("Analytics unavailable","تحلیل‌ها در دسترس نیستند")}/></main>;const a=state.data;return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("REGISTRY RANKINGS","رتبه‌بندی سامانه ثبت")} title={L("Rankings grounded in recorded registry structure","رتبه‌بندی بر پایه ساختار ثبت‌شده سامانه ثبت")} copy={L("No genomic, speed, earnings or market leaderboard is fabricated. These ranks come from progeny, ancestry representation and people-network counts.","هیچ رتبه ژنومی، سرعت، درآمد یا بازار ساخته نمی‌شود. این رتبه‌ها از فرزندان ثبت‌شده، حضور نیاکان و شبکه افراد می‌آیند.")}/><div className="edx-ranking-grid"><RankBlock title={L("Top sires by recorded offspring","برترین پدران بر اساس فرزند ثبت‌شده")} rows={a.progeny.topSires} view={view}/><RankBlock title={L("Top dams by recorded offspring","برترین مادران بر اساس فرزند ثبت‌شده")} rows={a.progeny.topDams} view={view}/><RankBlock title={L("Most represented ancestors · depth 4","پرتکرارترین نیاکان · عمق ۴")} rows={a.pedigree.topRepresentedAncestorsDepth4} view={view}/>{a.people&&<RankPeople title={L("Top owners by linked horses","برترین مالکان بر اساس اسب مرتبط")} rows={a.people.topOwners} view={view}/>} {a.people&&<RankPeople title={L("Top breeders by linked horses","برترین پرورش‌دهندگان بر اساس اسب مرتبط")} rows={a.people.topBreeders} view={view}/>} {a.people&&<RankPeople title={L("Top importers by linked horses","برترین واردکنندگان بر اساس اسب مرتبط")} rows={a.people.topImporters} view={view}/>} {a.people&&<RankPeople title={L("Top passport receivers by linked horses","برترین گیرندگان گذرنامه بر اساس اسب مرتبط")} rows={a.people.topPassportReceivers} view={view}/>}</div><DormantFeature title={L("Genomic / performance / market leaderboards","رتبه‌بندی ژنومی / عملکرد / بازار")} reason={L("Those rankings require datasets Horse DB does not currently possess. Their original UI remains preserved for a future compatible backend.","این رتبه‌بندی‌ها به داده‌هایی نیاز دارند که Horse DB فعلاً ندارد؛ رابط اصلی آن‌ها برای سرویس سازگار آینده حفظ شده است.")}/></main>}
function RankBlock({title,rows,view}:{title:string;rows:Array<{id:number;name_latin?:string|null;name_native?:string|null;count:number}>;view:EquiDataRuntime}){return <Panel><h3>{title}</h3><div className="edx-rank-list">{rows.map((r,i)=><button key={r.id} onClick={()=>view.navigate(horseDbRoutes.horse(r.id))}><span>#{num(i+1,view.locale)}</span><strong dir="auto">{horseName({id:r.id,name_latin:r.name_latin||"",name_native:r.name_native},view.locale)}</strong><small>{num(r.count,view.locale)}</small></button>)}</div></Panel>}
function RankPeople({title,rows,view}:{title:string;rows:Array<{id:number;name_latin?:string|null;name_native?:string|null;count:number}>;view:EquiDataRuntime}){return <Panel><h3>{title}</h3><div className="edx-rank-list">{rows.map((r,i)=><button key={r.id} onClick={()=>view.navigate(horseDbRoutes.person(r.id))}><span>#{num(i+1,view.locale)}</span><strong dir="auto">{(view.locale==="fa"?r.name_native||r.name_latin:r.name_latin||r.name_native)||`${edxText(view.locale,"Person","فرد")} #${num(r.id,view.locale)}`}</strong><small>{num(r.count,view.locale)}</small></button>)}</div></Panel>}

export function BreedingLabPage({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const [sire,setSire]=useState<HorseRecord|null>(null);const [dam,setDam]=useState<HorseRecord|null>(null);const [depth,setDepth]=useState(8);
  const scope=usePrincipalScope(view.user,view.permissions);
  const [pairQuery,setPairQuery]=useState<{sire:HorseRecord;dam:HorseRecord;depth:number;revision:number}|null>(null);
  const pair=useDomainResource('elite-pedigree-pair',`${scope}:${JSON.stringify(pairQuery)}`,signal=>view.platform.breeding.pairingAnalysis(pairQuery!.sire.id,pairQuery!.dam.id,{depth:pairQuery!.depth},{signal}),{enabled:view.capabilities.breeding&&pairQuery!=null});
  const result=pair.state.phase==='ready'||pair.state.phase==='reloading'?pair.state.data:null;
  const busy=pair.state.phase==='loading'||pair.state.phase==='reloading';
  const[optimizerRole,setOptimizerRole]=useState<"sire"|"dam">("sire");const[optimizerQuery,setOptimizerQuery]=useState("");const[optimizerOptions,setOptimizerOptions]=useState<HorseRecord[]>([]);const[optimizerCandidates,setOptimizerCandidates]=useState<HorseRecord[]>([]);
  const[optimizerRequest,setOptimizerRequest]=useState<{fixedHorseId:number;fixedRole:'sire'|'dam';candidateIds:number[];depth:number;revision:number}|null>(null);
  const ranking=useDomainResource('elite-pedigree-ranking',`${scope}:${JSON.stringify(optimizerRequest)}`,signal=>{const {revision,...input}=optimizerRequest!;return view.platform.breeding.optimize(input,{signal});},{enabled:optimizerRequest!=null});
  const optimizerResult=ranking.state.phase==='ready'||ranking.state.phase==='reloading'?ranking.state.data:null;
  const optimizerBusy=ranking.state.phase==='loading'||ranking.state.phase==='reloading';
  const failedResource=[pair,ranking].find(item=>['error','forbidden','unavailable'].includes(item.state.phase));
  const error=failedResource?(failedResource.state.phase==='forbidden'?L('This account cannot access this analysis.','این حساب به این تحلیل دسترسی ندارد.'):failedResource.state.phase==='unavailable'?L('This analysis is unavailable in this environment.','این تحلیل در این محیط در دسترس نیست.'):L('The analysis could not be loaded. Your inputs are preserved.','تحلیل بارگیری نشد. ورودی‌های شما حفظ شده‌اند.')):'';
  const optimizerFixed=optimizerRole==="sire"?sire:dam;
  useEffect(()=>{setOptimizerOptions([]);if(optimizerQuery.trim().length<2)return;const controller=new AbortController();const timer=setTimeout(()=>view.platform.search.horses(optimizerQuery,{limit:8,signal:controller.signal}).then(x=>{if(!controller.signal.aborted)setOptimizerOptions(x.results.filter(h=>h.id!==optimizerFixed?.id&&!optimizerCandidates.some(c=>c.id===h.id)))}).catch(()=>{if(!controller.signal.aborted)setOptimizerOptions([])}),180);return()=>{clearTimeout(timer);controller.abort()}},[view.platform,scope,optimizerQuery,optimizerFixed?.id,optimizerCandidates]);
  const run=()=>{if(!sire||!dam||sire.id===dam.id||busy||!view.capabilities.breeding)return;setPairQuery(previous=>({sire,dam,depth,revision:(previous?.revision??0)+1}));};
  const optimize=()=>{if(!optimizerFixed||!optimizerCandidates.length||optimizerBusy)return;setOptimizerRequest(previous=>({fixedHorseId:optimizerFixed.id,fixedRole:optimizerRole,candidateIds:optimizerCandidates.map(x=>x.id),depth:Math.min(depth,12),revision:(previous?.revision??0)+1}));};
  return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("BREEDING LAB","آزمایشگاه جفت‌گیری")} title={L("Prospective pedigree pairing analysis","تحلیل تبارنامه‌ای جفت پیشنهادی")} copy={L("Compare recorded pedigree and reviewed genetic evidence, with the limits of each result shown alongside it.","تبار ثبت‌شده و شواهد ژنتیکی بررسی‌شده را مقایسه کنید؛ محدودیت هر نتیجه در کنار آن نمایش داده می‌شود.")}/>{!view.capabilities.breeding?<DormantFeature title={L("Breeding analysis","تحلیل جفت‌گیری")} reason={L("This backend does not expose breeding_analysis.","این سرویس قابلیت breeding_analysis را ارائه نمی‌کند.")}/>:<><div className="edx-picker-grid two"><HorsePicker platform={view.platform} locale={view.locale} label={L("SIRE","پدر")} value={sire} onChange={value=>{setSire(value);setPairQuery(null);setOptimizerRequest(null)}}/><HorsePicker platform={view.platform} locale={view.locale} label={L("DAM","مادر")} value={dam} onChange={value=>{setDam(value);setPairQuery(null);setOptimizerRequest(null)}}/></div><Panel className="edx-lab-controls"><label>{L("Pedigree depth","عمق تبارنامه")} <select value={depth} onChange={e=>{setDepth(Number(e.target.value));setPairQuery(null);setOptimizerRequest(null);}}>{[4,6,8,10,12,16].map(d=><option key={d} value={d}>{num(d,view.locale)} {L("generations","نسل")}</option>)}</select></label><button className="edx-button primary" disabled={!sire||!dam||sire.id===dam.id||busy} onClick={run}>{busy?L("ANALYZING…","در حال تحلیل…"):L("ANALYZE PAIRING","تحلیل جفت")} <Icon name="lab"/></button>{sire&&dam&&sire.id===dam.id&&<small className="edx-error-text">{L("Select two different horses.","دو اسب متفاوت انتخاب کنید.")}</small>}</Panel>{error&&<div role="alert"><ErrorPanel error={error}/><button type="button" className="edx-button" onClick={failedResource?.retry}>{L("Try again","تلاش دوباره")}</button></div>} {result&&<PairingResult view={view} result={result} sire={pairQuery!.sire} dam={pairQuery!.dam}/>}<Panel className="edx-breeding-optimizer"><SectionTitle eyebrow={L("PEDIGREE DECISION OPTIMIZER","بهینه‌ساز تصمیم تبارنامه‌ای")} title={L("Rank a candidate set against one fixed parent","رتبه‌بندی مجموعه نامزدها در برابر یک والد ثابت")} copy={L("Explainable confidence-adjusted scoring combines projected offspring COI, ancestor diversity, low concentration and candidate diversity-preservation context when available.","امتیازدهی قابل توضیح و تعدیل‌شده با اعتماد، COI فرزند، تنوع نیاکان، تمرکز پایین و زمینه حفظ تنوع نامزد را در صورت وجود ترکیب می‌کند.")}/><div className="edx-optimizer-role"><button className={optimizerRole==="sire"?"active":""} onClick={()=>{setOptimizerRole("sire");setOptimizerRequest(null)}}>{L("Fixed sire","پدر ثابت")}<small dir="auto">{sire?horseName(sire,view.locale):L("not selected","انتخاب نشده")}</small></button><button className={optimizerRole==="dam"?"active":""} onClick={()=>{setOptimizerRole("dam");setOptimizerRequest(null)}}>{L("Fixed dam","مادر ثابت")}<small dir="auto">{dam?horseName(dam,view.locale):L("not selected","انتخاب نشده")}</small></button></div>{optimizerFixed?<><div className="edx-searchbox large"><Icon name="search"/><input dir="auto" value={optimizerQuery} onChange={e=>setOptimizerQuery(e.target.value)} placeholder={L("Search candidate horses…","جست‌وجوی اسب‌های نامزد…")}/>{optimizerOptions.length>0&&<div className="edx-optimizer-search-results">{optimizerOptions.map(h=><button key={h.id} onClick={()=>{if(optimizerCandidates.length<12&&!optimizerCandidates.some(x=>x.id===h.id)){setOptimizerCandidates(list=>[...list,h]);setOptimizerRequest(null)}setOptimizerQuery("");setOptimizerOptions([])}}><b dir="auto">{horseName(h,view.locale)}</b><small>#{num(h.id,view.locale)} · {h.birth_year??"—"}</small></button>)}</div>}</div><div className="edx-optimizer-chips">{optimizerCandidates.map(h=><button key={h.id} onClick={()=>{setOptimizerCandidates(list=>list.filter(x=>x.id!==h.id));setOptimizerRequest(null)}}><span dir="auto">{horseName(h,view.locale)}</span><small>#{num(h.id,view.locale)}</small><b>×</b></button>)}</div><button className="edx-button primary" disabled={!optimizerCandidates.length||optimizerBusy} onClick={optimize}>{optimizerBusy?L("RANKING…","در حال رتبه‌بندی…"):L("RANK CANDIDATES","رتبه‌بندی نامزدها")}</button></>:<p className="edx-science-note">{L("Select the fixed sire or dam first.","ابتدا پدر یا مادر ثابت را انتخاب کنید.")}</p>}{optimizerResult?<EquiDataOptimizerResult view={view} result={optimizerResult}/>:null}</Panel></>}<div className="edx-dormant-grid"><DormantFeature title={L("Projected genomic traits","صفات ژنومی پیش‌بینی‌شده")} reason={L("Requires real genomic data and a validated inheritance model.","به داده ژنومی واقعی و مدل وراثت اعتبارسنجی‌شده نیاز دارد.")}/><DormantFeature title={L("Projected market ceiling","سقف ارزش بازار پیش‌بینی‌شده")} reason={L("Requires a validated market dataset and valuation methodology.","به داده بازار و روش ارزش‌گذاری اعتبارسنجی‌شده نیاز دارد.")}/></div></main>
}
function PairingResult({view,result,sire,dam}:{view:EquiDataRuntime;result:BreedingPairingAnalysisResponse;sire:HorseRecord;dam:HorseRecord}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const scope=usePrincipalScope(view.user,view.permissions);return <Panel className="edx-pairing-result"><SectionTitle eyebrow={L("PAIRING RESULT","نتیجه جفت‌گیری")} title={<><span dir="auto">{horseName(sire,view.locale)}</span> × <span dir="auto">{horseName(dam,view.locale)}</span></>} copy={L("Prospective offspring pedigree COI equals parental kinship at the selected finite depth.","ضریب هم‌خونی تبارنامه‌ای فرزند احتمالی برابر هم‌تباری والدین در عمق محدود انتخاب‌شده است.")}/><div className="edx-gauge-row"><CoefficientGauge label={L("Projected offspring pedigree COI","ضریب هم‌خونی پیش‌بینی‌شده فرزند")} percentValue={result.projectedOffspringInbreedingPercent} note={`${L("depth","عمق")} ${num(result.depth,view.locale)}`}/><CoefficientGauge label={L("Parental relationship","خویشاوندی والدین")} percentValue={result.parentalRelationshipPercent} note={L("normalized pedigree relationship","خویشاوندی تبارنامه‌ای نرمال‌شده")}/></div><div className="edx-metrics-grid"><Metric label={L("Sire pedigree coverage","پوشش تبارنامه پدر")} value={pct(result.sirePedigreeCompletenessPercent)} tone="cyan"/><Metric label={L("Dam pedigree coverage","پوشش تبارنامه مادر")} value={pct(result.damPedigreeCompletenessPercent)} tone="gold"/><Metric label={L("Shared ancestors","نیاکان مشترک")} value={num(result.commonAncestors.length,view.locale)} tone="green"/><Metric label={L("Integrity","یکپارچگی")} value={result.status.toUpperCase()} tone={result.status==="ok"?"green":"rose"}/></div>{result.diversityProjection&&<Panel className={`edx-pairing-diversity confidence-${result.diversityProjection.confidence.grade}`}><h3>{L("Projected offspring pedigree diversity","تنوع تبارنامه‌ای پیش‌بینی‌شده فرزند")}</h3><div className="edx-metrics-grid compact"><Metric label={L("Projected completeness","کامل‌بودن پیش‌بینی‌شده")} value={pct(result.diversityProjection.projectedPedigreeCompletenessPercent)} tone="cyan"/><Metric label={L("Unique ancestors","نیاکان یکتا")} value={num(result.diversityProjection.projectedUniqueRecordedAncestors,view.locale)} tone="green"/><Metric label={L("Repeated positions","جایگاه تکراری")} value={num(result.diversityProjection.projectedRepeatedAncestorPositions,view.locale)} tone="rose"/><Metric label={L("Ancestor diversity","تنوع نیاکان")} value={pct(result.diversityProjection.projectedAncestorDiversityPercent)} tone="gold"/><Metric label={L("Shared parent ancestry","نیای مشترک والدین")} value={num(result.diversityProjection.sharedRecordedAncestorsBetweenParents,view.locale)} tone="muted"/><Metric label={L("Top-5 concentration","تمرکز ۵ برتر")} value={pct(result.diversityProjection.projectedTop5RecordedPathWeightSharePercent)} tone="gold"/></div><EquiDataPairingScience view={view} projection={result.diversityProjection}/><div className="edx-premium-ancestor-grid">{result.diversityProjection.topProjectedAncestorContributions.map(a=><button key={a.horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><strong dir="auto">{horseName(a.horse,view.locale)}</strong><span>{pct(a.shareOfRecordedPathWeightPercent)}{a.fromSire&&a.fromDam?` · ${L("both parents","هر دو والد")}`:""}</span></button>)}</div><p className="edx-science-note">{localizedAnalysisText(result.diversityProjection.provenance.interpretation,view.locale)}</p></Panel>}<p className="edx-science-note">{localizedAnalysisText(result.provenance.interpretation,view.locale)}</p>{result.commonAncestors.length>0&&<div className="edx-common-ancestors">{result.commonAncestors.map(a=><button key={a.horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><strong dir="auto">{horseName(a.horse,view.locale)}</strong><span>#{num(a.horse.id,view.locale)} · {L("nearest","نزدیک‌ترین")} G{num(a.fromDepth,view.locale)}/G{num(a.toDepth,view.locale)}</span></button>)}</div>}<ArabianPairingPanel platform={view.platform} sireId={result.sireId} damId={result.damId} locale={view.locale} principalScope={scope}/></Panel>}
function EquiDataPairingScience({view,projection}:{view:EquiDataRuntime;projection:NonNullable<BreedingPairingAnalysisResponse["diversityProjection"]>}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);return <details className="edx-pairing-science"><summary>{L("Full projected diversity ledger","دفتر کامل تنوع پیش‌بینی‌شده")}</summary><div className="edx-reference-method"><div><small>{L("Known / expected positions","جایگاه معلوم / مورد انتظار")}</small><b>{num(projection.projectedKnownAncestorPositions,view.locale)} / {num(projection.projectedExpectedAncestorPositions,view.locale)}</b></div><div className="tone-sire"><small>{L("Sire unique ancestors","نیاکان یکتای پدر")}</small><b>{num(projection.sireUniqueRecordedAncestors,view.locale)}</b></div><div className="tone-dam"><small>{L("Dam unique ancestors","نیاکان یکتای مادر")}</small><b>{num(projection.damUniqueRecordedAncestors,view.locale)}</b></div><div className="tone-gold"><small>{L("Top-10 concentration","تمرکز ۱۰ برتر")}</small><b>{pct(projection.projectedTop10RecordedPathWeightSharePercent)}</b></div><div><small>{L("Depth / algorithm","عمق / الگوریتم")}</small><b>G{num(projection.depth,view.locale)} · {projection.provenance.algorithmVersion}</b></div></div>{projection.confidence.reasons.map((reason,i)=><p className="edx-science-note" key={i}>ⓘ {reason}</p>)}</details>}

function EquiDataOptimizerResult({view,result}:{view:EquiDataRuntime;result:BreedingOptimizerResponse}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);return <div className="edx-optimizer-results"><header><span>{L("Rank","رتبه")}</span><span>{L("Candidate","نامزد")}</span><span>{L("Adjusted score","امتیاز تعدیل‌شده")}</span><span>COI</span><span>{L("Diversity","تنوع")}</span><span>DPI</span><span>{L("Data quality","کیفیت داده")}</span></header>{result.ranked.map(row=><button className={row.rank===1?"rank-best":row.rank<=3?"rank-top":""} key={row.candidate.id} onClick={()=>view.navigate(horseDbRoutes.horse(row.candidate.id))}><b>#{num(row.rank,view.locale)}</b><span dir="auto"><strong>{horseName(row.candidate,view.locale)}</strong><small>#{num(row.candidate.id,view.locale)}</small></span><strong className="metric-score">{num(row.confidenceAdjustedScore,view.locale)}</strong><span className="metric-coi">{row.projectedOffspringInbreedingPercent==null?"—":pct(row.projectedOffspringInbreedingPercent)}</span><span className="metric-diversity">{row.projectedAncestorDiversityPercent==null?"—":pct(row.projectedAncestorDiversityPercent)}</span><span className="metric-dpi">{row.candidateDiversityPreservationIndex==null?"—":num(row.candidateDiversityPreservationIndex,view.locale)}</span><em className={`confidence-${row.confidenceGrade}`}>{row.confidenceGrade}</em></button>)}<EquiDataOptimizerScience view={view} result={result}/><footer>{localizedAnalysisText(result.provenance.interpretation,view.locale)}<br/>{localizedAnalysisText(result.provenance.caveat,view.locale)}</footer></div>}
function EquiDataOptimizerScience({view,result}:{view:EquiDataRuntime;result:BreedingOptimizerResponse}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);return <details className="edx-optimizer-science"><summary>{L("Scoring ledger, objectives & warnings","دفتر امتیاز، اهداف و هشدارها")}</summary><div className="edx-reference-method"><div><small>{L("Fixed role / horse","نقش / اسب ثابت")}</small><b>{result.fixedRole} · #{num(result.fixedHorseId,view.locale)}</b></div><div><small>{L("Evaluated / depth","ارزیابی / عمق")}</small><b>{num(result.evaluatedCandidates,view.locale)} · G{num(result.depth,view.locale)}</b></div><div className="tone-rose"><small>{L("COI ceiling","سقف COI")}</small><b>{pct(result.objectives.coiCeilingPercent)}</b></div><div><small>{L("Weights COI / diversity / concentration / DPI","وزن COI / تنوع / تمرکز / DPI")}</small><b>{result.objectives.lowProjectedCoiWeight}/{result.objectives.ancestorDiversityWeight}/{result.objectives.lowConcentrationWeight}/{result.objectives.candidateDiversityPreservationWeight}</b></div><div><small>{L("Avoid ancestors","پرهیز از نیاکان")}</small><b>{result.objectives.avoidAncestorIds.length?result.objectives.avoidAncestorIds.map(x=>`#${num(x,view.locale)}`).join(" · "):"—"}</b></div><div><small>{L("Strict exclusion","حذف سخت")}</small><b>{result.objectives.excludeAvoidedAncestors?L("yes","بله"):L("no","خیر")}</b></div></div><div className="edx-optimizer-breakdown">{result.ranked.map(row=><article key={row.candidate.id} className={row.rank===1?"rank-best":row.rank<=3?"rank-top":""}><header><b>#{num(row.rank,view.locale)} · <span dir="auto">{horseName(row.candidate,view.locale)}</span></b><span>{L("raw","خام")} {num(row.score,view.locale)} · {L("adjusted","تعدیل")} {num(row.confidenceAdjustedScore,view.locale)}</span></header><div className="edx-optimizer-row-science"><span>{L("Top-5 concentration","تمرکز ۵ برتر")} <b>{row.projectedTop5RecordedPathWeightSharePercent==null?"—":pct(row.projectedTop5RecordedPathWeightSharePercent)}</b></span><span>{L("Completeness","کامل‌بودن")} <b>{row.projectedPedigreeCompletenessPercent==null?"—":pct(row.projectedPedigreeCompletenessPercent)}</b></span><span>{L("Shared ancestors","نیاکان مشترک")} <b>{row.sharedRecordedAncestorsBetweenParents==null?"—":num(row.sharedRecordedAncestorsBetweenParents,view.locale)}</b></span><span>S/D <b>#{num(row.sireId,view.locale)} / #{num(row.damId,view.locale)}</b></span></div><div className="edx-score-components">{row.scoreComponents.map(c=><span key={c.code}><small>{c.code}</small><b>{c.normalizedScore==null?"—":num(c.normalizedScore,view.locale)}</b><em>{c.appliedWeight.toFixed(3)} / {c.nominalWeight.toFixed(3)}</em></span>)}</div>{row.avoidedAncestorsPresent.length?<p className="edx-science-warning">⚠ {L("Avoided ancestors present","نیاکان مورد پرهیز حاضرند")}: {row.avoidedAncestorsPresent.map(x=>`#${num(x,view.locale)}`).join(" · ")}</p>:null}{row.warnings.map((warning,i)=><p className="edx-science-warning" key={i}>⚠ {warning}</p>)}</article>)}</div><footer>{analysisMethodLabel(result.provenance.method,view.locale)} · {result.provenance.algorithmVersion}<br/>{localizedAnalysisText(result.provenance.caveat,view.locale)}</footer></details>}

export function StatsPage({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const [tab,setTab]=useState<"overview"|"bloodlines"|"breeding"|"premium"|"population"|"people"|"quality">("overview");
  const state=useAsyncValue(signal=>view.capabilities.analytics?view.platform.analytics.registry({signal}):Promise.reject(new Error(L("Registry analytics unavailable","تحلیل سامانه ثبت در دسترس نیست"))),[view.platform,view.capabilities.analytics,view.locale]);
  if(state.status==="loading")return <main className="edx-content edx-page"><LoadingPanel label={L("Loading registry observatory…","در حال بارگذاری رصدخانه سامانه ثبت…")}/></main>;
  if(state.status==="error"||!state.data)return <main className="edx-content edx-page"><ErrorPanel error={state.error||L("Analytics unavailable","تحلیل‌ها در دسترس نیستند")}/></main>;
  const a=state.data; const depth6=a.pedigree.completeness.find(x=>x.depth===6); const parentage=a.parentage; const people=a.people; const quality=a.quality;

  const openHorse=(id:number)=>view.navigate(horseDbRoutes.horse(id)); const openPerson=(id:number)=>view.navigate(horseDbRoutes.person(id));
  const horseLabel=(r:{id:number;name_latin?:string|null;name_native?:string|null})=>view.locale==="fa"?(r.name_native||r.name_latin||`#${r.id}`):(r.name_latin||r.name_native||`#${r.id}`);
  const tabs:Array<[typeof tab,string]>=[["overview",L("OVERVIEW","نمای کلی")],["bloodlines",L("BLOODLINES","تبارها")],["breeding",L("BREEDING","تولیدمثل")],["premium",L("PREMIUM INTEL","تحلیل پیشرفته")],["population",L("POPULATION","جمعیت")],["people",L("PEOPLE","افراد")],["quality",L("DATA FIDELITY","کیفیت داده")]];
  return <main className="edx-content edx-page edx-observatory">
    <SectionTitle headingLevel={1} eyebrow={L("REGISTRY OBSERVATORY","رصدخانه سامانه ثبت")} title={L("Complete population intelligence","هوشمندی کامل جمعیت")} copy={`${L("Snapshot","تصویر آماری")} ${a.schemaVersion} · ${L("algorithm","الگوریتم")} ${a.algorithmVersion} · ${new Date(a.generatedAt).toLocaleDateString(view.locale==="fa"?"fa-IR":"en-US")}`}/>
    <div className="edx-profile-kpis edx-observatory-kpis"><Metric label={L("Canonical horses","اسب‌های مرجع")} value={num(a.horseCount,view.locale)} tone="cyan"/><Metric label={L("People network","شبکه افراد مرتبط")} value={num(people?.peopleCount,view.locale)} tone="gold"/><Metric label={L("Cycle-clean analysis","تحلیل بدون چرخه")} value={num(a.pedigree.analyticsEligibleHorseCount,view.locale)} tone="green"/><Metric label={L("Open quality findings","یافته‌های باز کیفیت داده")} value={num(quality?.openIssues,view.locale)} tone="rose"/></div>
    <nav className="edx-observatory-tabs" aria-label={L("Observatory sections","بخش‌های رصدخانه")}>{tabs.map(([id,label])=><button key={id} className={tab===id?"active":""} aria-current={tab===id?"page":undefined} onClick={()=>setTab(id)}>{label}</button>)}</nav>
    {tab==="overview"&&<div className="edx-observatory-grid two">
      <Panel className="edx-stat-card"><h3>{L("Parentage structure","ساختار والدین")}</h3>{parentage?<div className="edx-metrics-grid compact"><Metric label={L("Both parents","هر دو والد")} value={num(parentage.bothParents,view.locale)} note={pct(parentage.bothParentsPercent)} tone="green"/><Metric label={L("One parent","یک والد")} value={num(parentage.oneParent,view.locale)} note={pct(parentage.oneParentPercent)} tone="gold"/><Metric label={L("No parents","بدون والد")} value={num(parentage.noParents,view.locale)} note={pct(parentage.noParentsPercent)} tone="rose"/></div>:<EmptyPanel title={L("Parentage unavailable","ساختار والدین موجود نیست")} copy={L("This analytics snapshot predates parentage structure.","این تصویر آماری قدیمی‌تر از داده ساختار والدین است.")}/>}</Panel>
      <AnalyticsBars title={L("Birth-decade arc","قوس دهه‌های تولد")} rows={a.birthDecades.map(x=>({label:`${x.decade}s`,count:x.count}))} locale={view.locale} tone="cyan"/>{a.birthYears?.length?<AnalyticsBirthYears title={L("Exact birth-year history","تاریخچه دقیق سال تولد")} rows={a.birthYears} locale={view.locale}/>:null}{a.birthYearSummary?<Panel className="edx-stat-card"><h3>{L("Birth-year summary","خلاصه سال تولد")}</h3><div className="edx-metrics-grid compact"><Metric label={L("Earliest","قدیمی‌ترین")} value={a.birthYearSummary.earliest==null?"—":num(a.birthYearSummary.earliest,view.locale)} tone="muted"/><Metric label={L("Latest","جدیدترین")} value={a.birthYearSummary.latest==null?"—":num(a.birthYearSummary.latest,view.locale)} tone="cyan"/><Metric label={L("Median","میانه")} value={a.birthYearSummary.median==null?"—":num(a.birthYearSummary.median,view.locale)} tone="gold"/><Metric label={L("Peak year","سال اوج")} value={a.birthYearSummary.peakYear==null?"—":num(a.birthYearSummary.peakYear,view.locale)} note={`${num(a.birthYearSummary.peakYearCount,view.locale)} ${L("records","رکورد")}`} tone="green"/></div></Panel>:null}
      <Panel className="edx-stat-card"><h3>{L("Registry signal","سیگنال سامانه ثبت")}</h3><div className="edx-metrics-grid compact"><Metric label={L("6-gen average coverage","میانگین پوشش ۶ نسل")} value={pct(depth6?.averagePercent)} tone="cyan"/><Metric label={L("Horses with offspring","اسب‌های دارای فرزند")} value={num(a.progeny.horsesWithRecordedOffspring,view.locale)} tone="gold"/><Metric label={L("Cycle-affected pedigrees","تبارهای درگیر چرخه")} value={num(a.pedigree.cycleContaminatedHorseCount,view.locale)} tone="rose"/></div></Panel>
      <AnalyticsBars title={L("Top breeds","نژادهای پرتکرار")} rows={a.topBreeds.map(x=>({label:x.label,count:x.count}))} locale={view.locale} tone="gold"/>
    </div>}
    {tab==="bloodlines"&&<div className="edx-observatory-grid two">
      <Panel className="edx-stat-card span-2"><h3>{L("Pedigree completeness by depth","کامل‌بودن تبارنامه بر حسب عمق")}</h3><div className="edx-depth-grid">{a.pedigree.completeness.map(x=><article key={x.depth}><span>G{num(x.depth,view.locale)}</span><strong>{pct(x.averagePercent)}</strong><i><b style={{width:`${Math.min(100,x.averagePercent)}%`}}/></i><small>{L("avg","میانگین")} {pct(x.averagePercent)} · {L("median","میانه")} {pct(x.medianPercent)} · {num(x.fullyRecordedCount,view.locale)} {L("fully recorded","کامل")} · {num(x.halfOrBetterCount,view.locale)} ≥50%{x.eligibleHorseCount!=null?` · ${num(x.eligibleHorseCount,view.locale)} ${L("eligible","قابل تحلیل")}`:""}</small></article>)}</div></Panel>
      <Panel className="edx-stat-card"><h3>{L("Pedigree integrity","یکپارچگی تبارنامه")}</h3><div className="edx-metrics-grid compact"><Metric label={L("Eligible","قابل تحلیل")} value={num(a.pedigree.analyticsEligibleHorseCount,view.locale)} tone="green"/><Metric label={L("Cycle nodes","گره‌های چرخه")} value={num(a.pedigree.cycleNodeCount,view.locale)} tone="rose"/><Metric label={L("Cycle affected","درگیر چرخه")} value={num(a.pedigree.cycleContaminatedHorseCount,view.locale)} tone="gold"/></div><p className="edx-science-note">{a.pedigree.cyclePolicy||a.pedigree.representationInterpretation}</p></Panel>
      <AnalyticsHorseRanks title={L("Most represented ancestors · depth 4","پرتکرارترین نیاکان · عمق ۴")} rows={a.pedigree.topRepresentedAncestorsDepth4} locale={view.locale} label={horseLabel} onOpen={openHorse}/>
    </div>}
    {tab==="breeding"&&<div className="edx-observatory-grid two">
      <AnalyticsHistogram title={L("Recorded offspring distribution","توزیع فرزندان ثبت‌شده")} rows={a.progeny.histogram??[]} locale={view.locale}/>
      <Panel className="edx-stat-card"><h3>{L("Progeny thresholds","آستانه‌های فرزند")}</h3><div className="edx-threshold-grid">{Object.entries(a.progeny.percentiles).map(([key,value])=><div key={key}><small>{key.toUpperCase()}</small><strong>{num(value,view.locale)}</strong></div>)}</div><p className="edx-science-note">{num(a.progeny.horsesWithRecordedOffspring,view.locale)} {L("horses have at least one recorded offspring.","اسب حداقل یک فرزند ثبت‌شده دارند.")}</p></Panel>
      <AnalyticsHorseRanks title={L("Top recorded parents","برترین والدین ثبت‌شده")} rows={a.progeny.topParents} locale={view.locale} label={horseLabel} onOpen={openHorse}/><AnalyticsHorseRanks title={L("Top recorded sires","برترین پدران ثبت‌شده")} rows={a.progeny.topSires} locale={view.locale} label={horseLabel} onOpen={openHorse}/>
      <AnalyticsHorseRanks title={L("Top recorded dams","برترین مادران ثبت‌شده")} rows={a.progeny.topDams} locale={view.locale} label={horseLabel} onOpen={openHorse}/>
    </div>}
    {tab==="premium"&&<EquiDataPremiumRegistry view={view} analytics={a}/>}
    {tab==="population"&&<div className="edx-observatory-grid two">
      <AnalyticsBars title={L("Recorded sex classes","کلاس‌های جنسیت ثبت‌شده")} rows={a.sexDistribution.map(x=>({label:edxSexLabel(view.locale,x.label),count:x.count}))} locale={view.locale} tone="cyan"/>
      {a.activity?<AnalyticsActivity activity={a.activity} locale={view.locale}/>:<Panel><h3>{L("Registry flags","نشانگر‌های سامانه ثبت")}</h3><p className="edx-science-note">{L("This snapshot predates registry activity flags.","این تصویر آماری قدیمی‌تر از نشانگر‌های سامانه ثبت است.")}</p></Panel>}
      <AnalyticsBars title={L("Top birth places","محل‌های تولد پرتکرار")} rows={a.topBirthPlaces.map(x=>({label:x.label,count:x.count}))} locale={view.locale} tone="green"/>
      <AnalyticsBars title={L("Top colors","رنگ‌های پرتکرار")} rows={(a.topColors??[]).map(x=>({label:x.label,count:x.count}))} locale={view.locale} tone="gold"/>
      <AnalyticsBars title={L("Top main strains","تیره‌های اصلی پرتکرار")} rows={(a.topMainStrains??[]).map(x=>({label:x.label,count:x.count}))} locale={view.locale} tone="rose"/>
      <AnalyticsBars title={L("Top breeds","نژادهای پرتکرار")} rows={a.topBreeds.map(x=>({label:x.label,count:x.count}))} locale={view.locale} tone="cyan"/>
    </div>}
    {tab==="people"&&<div className="edx-observatory-grid two">
      <Panel className="edx-stat-card span-2"><h3>{L("People network coverage","پوشش شبکه افراد")}</h3><div className="edx-profile-kpis compact"><Metric label={L("People","افراد")} value={num(people?.peopleCount,view.locale)} tone="cyan"/><Metric label={L("Owners","مالکان")} value={num(people?.ownerCount,view.locale)} tone="gold"/><Metric label={L("Breeders","پرورش‌دهندگان")} value={num(people?.breederCount,view.locale)} tone="green"/><Metric label={L("Importers","واردکنندگان")} value={num(people?.importerCount,view.locale)} tone="rose"/><Metric label={L("Passport receivers","گیرندگان گذرنامه")} value={num(people?.passportReceiverCount,view.locale)} tone="cyan"/><Metric label={L("Horses with owner","اسب با مالک")} value={num(people?.horsesWithOwner,view.locale)} tone="cyan"/><Metric label={L("Horses with breeder","اسب با پرورش‌دهنده")} value={num(people?.horsesWithBreeder,view.locale)} tone="green"/><Metric label={L("Horses with importer","اسب با واردکننده")} value={num(people?.horsesWithImporter,view.locale)} tone="rose"/><Metric label={L("Horses with passport receiver","اسب با گیرنده گذرنامه")} value={num(people?.horsesWithPassportReceiver,view.locale)} tone="gold"/></div></Panel>
      <AnalyticsPeopleRanks title={L("Most connected owners","مالکان با بیشترین ارتباط")} rows={people?.topOwners??[]} locale={view.locale} label={horseLabel} onOpen={openPerson}/>
      <AnalyticsPeopleRanks title={L("Most connected breeders","پرورش‌دهندگان با بیشترین ارتباط")} rows={people?.topBreeders??[]} locale={view.locale} label={horseLabel} onOpen={openPerson}/>
      <AnalyticsPeopleRanks title={L("Most connected importers","واردکنندگان با بیشترین ارتباط")} rows={people?.topImporters??[]} locale={view.locale} label={horseLabel} onOpen={openPerson}/>
      <AnalyticsPeopleRanks title={L("Most connected passport receivers","گیرندگان گذرنامه با بیشترین ارتباط")} rows={people?.topPassportReceivers??[]} locale={view.locale} label={horseLabel} onOpen={openPerson}/>
    </div>}
    {tab==="quality"&&<div className="edx-observatory-grid two">
      <AnalyticsCoverage title={L("Field coverage","پوشش فیلدها")} rows={a.dataCoverage?.fields??[]} locale={view.locale}/>
      {a.completeness&&<Panel className="edx-stat-card span-2" data-surface="registry-completeness"><h3>{L("Recorded-data completeness measures","سنجه‌های کامل‌بودن داده ثبت‌شده")}</h3><p className="edx-science-note">{L("Five separate measures over the same denominator (all non-deleted canonical records). Recorded-data coverage only — never a verification or registry-completeness claim.","پنج سنجهٔ جداگانه روی یک مخرج مشترک (همه رکوردهای مرجع حذف‌نشده). فقط پوشش داده ثبت‌شده — نه ادعای راستی‌آزمایی یا کامل‌بودن سامانه ثبت.")}</p><div className="edx-completeness-grid" data-completeness-snapshot={a.completeness.snapshotTime}>{a.completeness.measures.map(measure=><article key={measure.key} className="edx-completeness-measure"><header><strong>{edxCompletenessLabel(view.locale,measure.key,measure.label)}</strong><span className="edx-completeness-count">{num(measure.coveredRecords,view.locale)} / {num(measure.totalRecords,view.locale)}</span></header><div className="edx-depth-grid">{measure.components?.map(component=><div key={component.key} title={component.missingDefinition}><span dir="auto">{component.label}</span><strong>{pct(component.coveragePercent)}</strong><i><b style={{width:`${Math.min(100,component.coveragePercent)}%`}}/></i><small>{num(component.coveredRecords,view.locale)}</small></div>)}</div><footer>{measure.missingDefinition}</footer></article>)}</div></Panel>}
      <Panel className="edx-stat-card"><h3>{L("Open data-quality findings","یافته‌های باز کیفیت داده")}</h3><div className="edx-profile-kpis compact"><Metric label={L("Open findings","یافته باز")} value={num(quality?.openIssues,view.locale)} tone="rose"/>{quality?.severities.map((row,index)=><Metric key={row.label} label={edxQualitySeverityLabel(view.locale,row.label)} value={num(row.count,view.locale)} tone={index===0?"rose":index===1?"gold":"cyan"}/>)}</div>{quality?.topIssueCodes.length?<div className="edx-issue-list">{quality.topIssueCodes.map(row=><div key={row.label}><span>{edxQualityIssueLabel(view.locale,row.label)}</span><strong>{num(row.count,view.locale)}</strong></div>)}</div>:null}</Panel>
      <AnalyticsEraCoverage title={L("Coverage by birth decade","پوشش بر حسب دهه تولد")} rows={a.dataCoverage?.byBirthDecade??[]} locale={view.locale}/>
    </div>}
    <p className="edx-science-note edx-observatory-provenance">{localizedAnalysisText(a.provenance.interpretation,view.locale)} · {L("Derived intelligence; canonical horse records remain the source of truth.","این شاخص‌ها از داده‌های سامانه ثبت محاسبه شده‌اند؛ رکورد مرجع اسب همچنان منبع اصلی حقیقت است.")} · {L("Source revision","بازبینی منبع")}: <code>{a.sourceRevision}</code></p>
  </main>
}

function AnalyticsBirthYears({title,rows,locale}:{title:string;rows:Array<{year:number;count:number}>;locale:"en"|"fa"|"ar"}){const max=Math.max(1,...rows.map(x=>x.count));const L=(en:string,fa:string)=>edxText(locale,en,fa);return <Panel className="edx-stat-card span-2 edx-birth-years"><div className="edx-chart-head"><h3>{title}</h3><span>{L("Scroll horizontally · hover a bar for the exact count","برای دیدن سال‌ها افقی پیمایش کنید · روی هر ستون بروید تا تعداد دقیق را ببینید")}</span></div><div className="edx-year-series" role="img" aria-label={title}>{rows.map((row,index)=>{const labelled=index===0||index===rows.length-1||row.year%10===0;return <div key={row.year} className={labelled?"tick":""} title={`${num(row.year,locale)} · ${num(row.count,locale)} ${L("records","رکورد")}`}><i><b style={{height:`${Math.max(row.count?3:0,row.count/max*100)}%`}}/></i><span>{labelled?num(row.year,locale):""}</span><small>{num(row.count,locale)}</small></div>})}</div></Panel>}
function AnalyticsBars({title,rows,locale,tone}:{title:string;rows:Array<{label:string;count:number}>;locale:"en"|"fa"|"ar";tone:"cyan"|"gold"|"green"|"rose"}){const max=Math.max(1,...rows.map(x=>x.count));return <Panel className={`edx-stat-card tone-${tone}`}><h3>{title}</h3>{rows.length?<div className="edx-bars edx-analytics-bars">{rows.map((x,index)=><div key={`${x.label}-${index}`}><span dir="auto">{x.label}</span><i><b style={{width:`${Math.max(x.count?2:0,x.count/max*100)}%`}}/></i><strong>{num(x.count,locale)}</strong></div>)}</div>:<span className="edx-stat-empty">—</span>}</Panel>}
function AnalyticsHorseRanks({title,rows,locale,label,onOpen}:{title:string;rows:Array<{id:number;name_latin?:string|null;name_native?:string|null;count:number}>;locale:"en"|"fa"|"ar";label:(r:{id:number;name_latin?:string|null;name_native?:string|null})=>string;onOpen:(id:number)=>void}){return <Panel className="edx-stat-card"><h3>{title}</h3><div className="edx-rank-list">{rows.map((r,i)=><button key={r.id} onClick={()=>onOpen(r.id)}><span>{String(i+1).padStart(2,"0")}</span><strong dir="auto">{label(r)}</strong><small>{num(r.count,locale)}</small></button>)}</div></Panel>}
function AnalyticsPeopleRanks({title,rows,locale,label,onOpen}:{title:string;rows:Array<{id:number;name_latin?:string|null;name_native?:string|null;count:number}>;locale:"en"|"fa"|"ar";label:(r:{id:number;name_latin?:string|null;name_native?:string|null})=>string;onOpen:(id:number)=>void}){return <Panel className="edx-stat-card"><h3>{title}</h3><div className="edx-rank-list edx-people-ranks">{rows.map((r,i)=><button key={r.id} onClick={()=>onOpen(r.id)}><span>{String(i+1).padStart(2,"0")}</span><strong dir="auto">{label(r)}</strong><small>{num(r.count,locale)}</small></button>)}</div></Panel>}
function AnalyticsHistogram({title,rows,locale}:{title:string;rows:Array<{label:string;count:number}>;locale:"en"|"fa"|"ar"}){const max=Math.max(1,...rows.map(x=>x.count));return <Panel className="edx-stat-card"><h3>{title}</h3><div className="edx-stat-histogram">{rows.map(row=><span key={row.label}><i><b style={{height:`${Math.max(row.count?2:0,row.count/max*100)}%`}}/></i><strong>{num(row.count,locale)}</strong><small dir="auto">{row.label}</small></span>)}</div></Panel>}
function AnalyticsActivity({activity,locale}:{activity:NonNullable<RegistryAnalyticsResponse["activity"]>;locale:"en"|"fa"|"ar"}){const L=(en:string,fa:string)=>edxText(locale,en,fa);const rows:Array<[keyof typeof activity,string,"cyan"|"gold"|"green"|"rose"]>=[["active",L("Active","فعال"),"green"],["deceased",L("Deceased","تلف‌شده"),"rose"],["imported",L("Imported","وارداتی"),"cyan"],["stallions",L("Stallion flag","سیلمی"),"gold"],["sport",L("Sport","ورزشی"),"green"],["sportCard",L("Sport card","کارت ورزشی"),"cyan"]];return <Panel className="edx-stat-card"><h3>{L("Registry flags","نشانگر‌های سامانه ثبت")}</h3><div className="edx-activity-grid">{rows.map(([key,label,tone])=><article className={`tone-${tone}`} key={key}><small>{label}</small><strong>{num(activity[key].count,locale)}</strong><span>{pct(activity[key].percent)}</span></article>)}</div></Panel>}
const EDX_COVERAGE_LABELS:Record<string,readonly [string,string]>={nativeName:["Native name","نام بومی"],registration:["Registration no.","شماره ثبت"],microchip:["Microchip","میکروچیپ"],birthYear:["Birth year","سال تولد"],birthPlace:["Birth place","محل تولد"],breed:["Breed","نژاد"],sex:["Sex","جنسیت"],color:["Color","رنگ"],mainStrain:["Main strain","تیره اصلی"],dnaRecord:["DNA/sample detail","جزئیات DNA/نمونه"],passport:["Passport no.","شماره گذرنامه"],bothParents:["Both parents","هر دو والد"],anyParent:["Any parent","حداقل یک والد"],owner:["Owner link","پیوند مالک"],breeder:["Breeder link","پیوند پرورش‌دهنده"],importer:["Importer link","پیوند واردکننده"],passportReceiver:["Passport receiver link","پیوند گیرنده گذرنامه"]};
function AnalyticsCoverage({title,rows,locale}:{title:string;rows:Array<{key:string;count:number;percent:number}>;locale:"en"|"fa"|"ar"}){const label=(key:string)=>{const pair=EDX_COVERAGE_LABELS[key];return pair?edxText(locale,pair[0],pair[1]):key.replace(/([A-Z])/g," $1").replaceAll("_"," ")};return <Panel className="edx-stat-card"><h3>{title}</h3><div className="edx-coverage-list">{rows.map(row=><div key={row.key}><span>{label(row.key)}</span><i><b style={{width:`${Math.max(0,Math.min(100,row.percent))}%`}}/></i><strong>{pct(row.percent)}</strong><small>{num(row.count,locale)}</small></div>)}</div></Panel>}
function AnalyticsEraCoverage({title,rows,locale}:{title:string;rows:Array<{decade:number;count:number;nativeNamePercent:number;registrationPercent:number;birthPlacePercent:number;bothParentsPercent:number}>;locale:"en"|"fa"|"ar"}){const L=(en:string,fa:string)=>edxText(locale,en,fa);return <Panel className="edx-stat-card span-2 edx-era-card"><h3>{title}</h3><div className="edx-era-table"><header><span>{L("Decade","دهه")}</span><span>{L("Records","رکورد")}</span><span>{L("Native name","نام بومی")}</span><span>{L("Registration","ثبت")}</span><span>{L("Birth place","محل تولد")}</span><span>{L("Both parents","هر دو والد")}</span></header>{rows.map(row=><div key={row.decade}><strong>{row.decade}s</strong><span>{num(row.count,locale)}</span><span>{pct(row.nativeNamePercent)}</span><span>{pct(row.registrationPercent)}</span><span>{pct(row.birthPlacePercent)}</span><span>{pct(row.bothParentsPercent)}</span></div>)}</div></Panel>}

export function PeoplePage({view}:{view:EquiDataRuntime}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const [q,setQ]=useState("");const [offset,setOffset]=useState(0);const limit=48;
  useEffect(()=>setOffset(0),[q]);
  const state=useAsyncValue(signal=>view.capabilities.people?view.platform.people.list({q:q||undefined,limit,offset},{signal}):Promise.reject(new Error(L("People capability unavailable","قابلیت افراد در دسترس نیست"))),[view.platform,q,offset,view.capabilities.people,view.locale]);
  const rows=state.data?.people??[];
  const from=rows.length?offset+1:0;
  const to=offset+rows.length;
  const hasNext=rows.length===limit;
  return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("PEOPLE NETWORK","شبکه افراد مرتبط")} title={L("People & registry roles","افراد و نقش‌های سامانه ثبت")} copy={L("Canonical people entities with full server-side traversal, search and linked-horse counts.","هویت‌های مرجع افراد با پیمایش کامل سمت سرور، جست‌وجو و تعداد اسب‌های مرتبط.")}/><div className="edx-searchbox large"><Icon name="search"/><input dir="auto" value={q} onChange={e=>setQ(e.target.value)} placeholder={L("Search people…","جست‌وجوی افراد…")}/></div>{state.status==="loading"&&!state.data?<LoadingPanel/>:state.status==="error"?<DormantFeature title={L("People network","شبکه افراد مرتبط")} reason={state.error||L("Unavailable","در دسترس نیست")}/>:<>{<div className="edx-people-grid">{rows.map(p=><button key={p.id} onClick={()=>view.navigate(horseDbRoutes.person(p.id))}><div className="edx-person-mark">{(p.name_latin||p.name_native||"?").slice(0,1).toUpperCase()}</div><strong dir="auto">{(view.locale==="fa"?p.name_native||p.name_latin:p.name_latin||p.name_native)||`${L("Person","فرد")} #${num(p.id,view.locale)}`}</strong><span>{num(p.horse_count,view.locale)} {L("linked horses","اسب مرتبط")}</span><small>{num(p.owner_count,view.locale)} {L("owner","مالک")} · {num(p.breeder_count,view.locale)} {L("breeder","پرورش‌دهنده")}{p.importer_count?` · ${num(p.importer_count,view.locale)} ${L("importer","واردکننده")}`:""}{p.passport_receiver_count?` · ${num(p.passport_receiver_count,view.locale)} ${L("passport receiver","گیرنده گذرنامه")}`:""}</small></button>)}</div>}<div className="edx-pagination"><button className="edx-button secondary" disabled={offset===0} onClick={()=>setOffset(Math.max(0,offset-limit))}>{view.locale==="fa"?"→":"←"} {L("Previous","قبلی")}</button><span>{rows.length?`${num(from,view.locale)}–${num(to,view.locale)}`:"—"}</span><button className="edx-button secondary" disabled={!hasNext} onClick={()=>setOffset(offset+limit)}>{L("Next","بعدی")} {view.locale==="fa"?"←":"→"}</button></div></>}</main>
}
export function PersonPage({view,id}:{view:EquiDataRuntime;id:number}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const state=useAsyncValue(signal=>view.platform.people.get(id,{signal}),[view.platform,id]);if(state.status==="loading")return <main className="edx-content edx-page"><LoadingPanel/></main>;if(state.status==="error"||!state.data)return <main className="edx-content edx-page"><ErrorPanel error={state.error||L("Person not found","فرد پیدا نشد")}/></main>;const p=state.data.person;return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={`${L("PERSON","فرد")} #${num(id,view.locale)}`} title={<span dir="auto">{(view.locale==="fa"?p.name_native||p.name_latin:p.name_latin||p.name_native)||`${L("Person","فرد")} #${num(id,view.locale)}`}</span>} copy={`${num(p.owner_count,view.locale)} ${L("ownership links","پیوند مالکیت")} · ${num(p.breeder_count,view.locale)} ${L("breeder links","پیوند پرورش‌دهندگی")} · ${num(p.importer_count,view.locale)} ${L("importer links","پیوند واردکننده")} · ${num(p.passport_receiver_count,view.locale)} ${L("passport-receiver links","پیوند گیرنده گذرنامه")}`}/><div className="edx-card-grid registry">{state.data.horses.map(h=><HorseCard headingLevel={2} key={`${h.id}-${h.role}`} horse={h} runtime={view} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>)}</div>{state.data.truncated&&<p className="edx-science-note">{L("This person profile is truncated by the current platform response limit.","این پروفایل فرد به دلیل حد پاسخ فعلی پلتفرم بریده شده است.")}</p>}</main>}

export function QualityPage({view}:{view:EquiDataRuntime}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const state=useAsyncValue(signal=>view.capabilities.quality?view.platform.quality.summary({signal}):Promise.reject(new Error(L("Quality capability unavailable","قابلیت کیفیت داده در دسترس نیست"))),[view.platform,view.capabilities.quality,view.locale]);return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("DATA QUALITY","کیفیت داده")} title={L("Registry integrity signal","سیگنال یکپارچگی سامانه ثبت")} copy={L("Public aggregate quality findings are shown here; privileged issue-level review is available in EquiData Control.","یافته‌های عمومی کیفیت به‌صورت تجمیعی اینجا نمایش داده می‌شوند؛ بررسی ممتاز در سطح هر یافته در کنترل EquiData در دسترس است.")}/>{state.status==="loading"?<LoadingPanel/>:state.status==="error"||!state.data?<DormantFeature title={L("Quality summary","خلاصه کیفیت")} reason={state.error||L("Unavailable","در دسترس نیست")}/>:<><div className="edx-profile-kpis"><Metric label={L("Open findings","یافته‌های باز")} value={num(state.data.openIssues,view.locale)} tone="rose"/>{state.data.severities.map(x=><Metric key={x.value} label={edxQualitySeverityLabel(view.locale,x.value)} value={num(x.count,view.locale)} tone="gold"/>)}</div><Panel><h3>{L("Most common finding codes","رایج‌ترین کدهای یافته")}</h3><div className="edx-rank-list">{state.data.topIssueCodes.map((x,i)=><div key={x.value}><span>#{num(i+1,view.locale)}</span><strong>{edxQualityIssueLabel(view.locale,x.value)}</strong><small>{num(x.count,view.locale)}</small></div>)}</div></Panel></>}</main>}

export function AssistantPage({view,goLocal}:{view:EquiDataRuntime;goLocal:GoLocal}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);if(!view.capabilities.ai)return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("AI RESEARCH ASSISTANT","دستیار پژوهشی هوش مصنوعی")} title={L("Assistant unavailable","دستیار در دسترس نیست")} copy={L("The deployment has not enabled the canonical AI assistant.","این استقرار دستیار مرجع هوش مصنوعی را فعال نکرده است.")}/></main>;return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("AI RESEARCH ASSISTANT","دستیار پژوهشی هوش مصنوعی")} title={L("Registry research, grounded in canonical data","پژوهش سامانه ثبت بر پایه داده مرجع")}/><AssistantPanel platform={view.platform} locale={view.locale} fullPage pageContext={{route:view.route}}/></main>}
export function WatchlistPage({view,favorites}:{view:EquiDataRuntime;favorites:FavoritesApi}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const state=useAsyncValue(async signal=>{const rows:HorseRecord[]=[];for(const id of favorites.ids){try{rows.push((await view.platform.horses.get(id,{signal})).horse)}catch{}}return rows},[view.platform,favorites.ids.join(",")]);return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("LOCAL WATCHLIST","فهرست پیگیری محلی")} title={`${num(favorites.count,view.locale)} ${L(favorites.count===1?"saved record":"saved records","رکورد ذخیره‌شده")}`} copy={L("Watchlist state is frontend-local and never presented as canonical registry truth.","فهرست پیگیری فقط محلی این رابط است و هرگز به‌عنوان حقیقت مرجع سامانه ثبت نمایش داده نمی‌شود.")} action={favorites.count?<button className="edx-button ghost" onClick={favorites.clear}>{L("CLEAR","پاک‌کردن")}</button>:undefined}/>{state.status==="loading"?<LoadingPanel/>:state.data?.length?<div className="edx-card-grid registry">{state.data.map(h=><HorseCard headingLevel={2} key={h.id} horse={h} runtime={view} favorite onFavorite={()=>favorites.toggle(h.id)} onOpen={()=>view.navigate(horseDbRoutes.horse(h.id))}/>)}</div>:<EmptyPanel title={L("Watchlist empty","فهرست پیگیری خالی است")} copy={L("Save horses from Registry Explorer or a profile.","از کاوشگر سامانه ثبت یا پروفایل اسب‌ها را ذخیره کنید.")}/>}</main>}

export function ClaimsPage({view}:{view:EquiDataRuntime}){return <EliteHorseRequestsPage view={view}/>;}
export function PlatformCapabilitiesPage({view,goLocal}:{view:EquiDataRuntime;goLocal:GoLocal}){
  const L=(en:string,fa:string)=>edxText(view.locale,en,fa);
  const searchMeta=useAsyncValue(signal=>view.platform.search.meta({signal}),[view.platform]);
  const catalog=Object.entries(view.platformMeta?.featureCatalog??{}) as Array<[PlatformFeatureKey,{available:boolean;version:string;stability:string;access:string}]>;
  const openFeature=(feature:PlatformFeatureKey)=>{
    if(["search","structured_search","registry","registry_facets","horse_profiles"].includes(feature))return ()=>view.navigate(horseDbRoutes.browse());
    if(feature==="people")return ()=>goLocal("/people");
    if(["pedigree_ancestors","pedigree_descendants","pedigree_metrics","pedigree_paths","pedigree_coefficients"].includes(feature))return ()=>goLocal("/pedigree/1");
    if(feature==="relationships")return ()=>goLocal("/compare");
    if(feature==="horse_insights")return ()=>view.navigate(horseDbRoutes.horse(1));
    if(feature==="registry_analytics")return ()=>view.navigate(horseDbRoutes.stats());
    if(feature==="quality_summary")return ()=>goLocal("/quality");
    if(feature==="owner_claims")return ()=>goLocal("/claims");
    if(feature==="authentication"||feature==="audit"||feature==="admin"||feature==="curation")return ()=>goLocal("/governance");
    if(feature==="change_requests")return ()=>goLocal("/claims");
    if(feature==="breeding_analysis")return ()=>goLocal("/breeding-lab");
    if(feature==="ai_assistant")return ()=>goLocal("/assistant");
    if(feature==="media")return ()=>view.navigate(horseDbRoutes.horse(1));
    if(feature==="performance_records")return ()=>view.navigate(horseDbRoutes.horse(1));
    if(feature==="market_data")return ()=>goLocal("/market");
    return null;
  };
  const labels:Partial<Record<PlatformFeatureKey,[string,string]>>={authentication:["Authentication","احراز هویت"],search:["Quick search","جست‌وجوی سریع"],structured_search:["Structured search","جست‌وجوی ساختاریافته"],registry:["Registry browser","مرور سامانه ثبت"],registry_facets:["Registry facets","دسته‌بندی‌های سامانه ثبت"],horse_profiles:["Horse profiles","پروفایل اسب"],people:["People network","شبکه افراد مرتبط"],pedigree_ancestors:["Ancestor pedigree","تبارنامه نیاکان"],pedigree_descendants:["Descendant graph","نمودار نوادگان"],pedigree_metrics:["Pedigree metrics","شاخص‌های تبارنامه"],pedigree_paths:["Ancestor paths","مسیرهای نیاکان"],pedigree_coefficients:["Pedigree coefficients","ضرایب تبارنامه"],relationships:["Relationship analysis","تحلیل خویشاوندی"],horse_insights:["Horse insights","بینش‌های اسب"],registry_analytics:["Registry analytics","تحلیل سامانه ثبت"],quality_summary:["Data quality","کیفیت داده"],owner_claims:["Ownership claims","ادعاهای مالکیت"],breeding_analysis:["Breeding analysis","تحلیل جفت‌گیری"],genomics:["Genomics","ژنومیک"],performance_records:["Performance records","سوابق عملکرد"],market_data:["Market data","داده بازار"],ai_assistant:["AI assistant","دستیار هوش مصنوعی"],media:["Media","رسانه"],verification:["Verification","تأیید اصالت"],change_requests:["Change requests","درخواست تغییر"],audit:["Audit","ممیزی"],admin:["Administration","مدیریت"],curation:["Curation","کیوریشن"],inspections:["Inspections","بازرسی"],exports:["Exports","خروجی‌ها"],breed_standards:["Breed standards","استاندارد نژاد"]};
  const live=catalog.filter(([,d])=>d.available).length;
  return <main className="edx-content edx-page"><SectionTitle headingLevel={1} eyebrow={L("PLATFORM COVERAGE","پوشش پلتفرم")} title={L("Every backend capability accounted for","همه قابلیت‌های سرویس مشخص‌اند")} copy={L("Available capabilities link to a real EquiData surface. Unavailable/reserved capabilities remain visible as dormant—never silently fabricated or deleted.","قابلیت‌های موجود به سطح واقعی EquiData متصل‌اند. قابلیت‌های رزروشده یا ناموجود به‌صورت غیرفعال دیده می‌شوند؛ نه پنهان، نه ساختگی.")}/><div className="edx-profile-kpis"><Metric label={L("Advertised features","قابلیت‌های اعلام‌شده")} value={num(catalog.length,view.locale)} tone="cyan"/><Metric label={L("Available now","فعال اکنون")} value={num(live,view.locale)} tone="green"/><Metric label={L("Dormant / reserved","غیرفعال / رزروشده")} value={num(catalog.length-live,view.locale)} tone="gold"/><Metric label={L("Contract","قرارداد")} value={view.platformMeta?.contractVersion??view.platform.contractVersion} tone="muted"/></div>{view.platformMeta?.source&&<section className="edx-source-proof"><header><span>{L("CANONICAL SOURCE PROVENANCE","منشأ منبع مرجع")}</span><b>{view.platformMeta.source.status.toUpperCase()}</b></header><dl><div><dt>{L("File","فایل")}</dt><dd>{view.platformMeta.source.filename}</dd></div><div><dt>{L("Sheet","برگه")}</dt><dd>{view.platformMeta.source.sheet}</dd></div><div><dt>{L("Rows","ردیف")}</dt><dd>{num(view.platformMeta.source.rowCount,view.locale)}</dd></div><div><dt>SHA-256</dt><dd title={view.platformMeta.source.sha256}>{view.platformMeta.source.sha256}</dd></div><div><dt>{L("Completed","تکمیل")}</dt><dd>{view.platformMeta.source.completedAt??"—"}</dd></div></dl></section>}{searchMeta.data&&<Panel className="edx-search-contract"><SectionTitle eyebrow={L("STRUCTURED SEARCH CONTRACT","قرارداد جست‌وجوی ساختاریافته")} title={`${L("Syntax","نحو")} ${searchMeta.data.syntaxVersion}`} copy={`${L("Maximum query length","حداکثر طول پرس‌وجو")}: ${num(searchMeta.data.maxQueryLength,view.locale)} · ${L("registry combinator","ترکیب سامانه ثبت")}: ${searchMeta.data.registryFieldSearch.combinator.toUpperCase()} · ${searchMeta.data.registryFieldSearch.version}`}/><div className="edx-capability-matrix compact">{searchMeta.data.fields.map(field=><article key={field.key} className="live"><header><span><strong>{field.key}</strong><code>{field.aliases.join(" · ")}</code></span></header></article>)}</div><div className="edx-search-field-map">{searchMeta.data.registryFieldSearch.fields.map(field=><span key={field.key}><b>{field.key}</b><code>{field.queryParam}</code><small>{field.type}</small></span>)}</div></Panel>}<div className="edx-capability-matrix">{catalog.map(([feature,descriptor])=>{const pair=labels[feature]??[feature,feature];const open=openFeature(feature);return <article key={feature} className={descriptor.available?"live":"dormant"}><header><span><i/><strong>{L(pair[0],pair[1])}</strong><code>{feature}</code></span><b>{edxStatus(view.locale,descriptor.available)}</b></header><dl><div><dt>{L("Version","نسخه")}</dt><dd>{descriptor.version}</dd></div><div><dt>{L("Stability","پایداری")}</dt><dd>{edxStabilityLabel(view.locale,descriptor.stability)}</dd></div><div><dt>{L("Access","دسترسی")}</dt><dd>{edxAccessLabel(view.locale,descriptor.access)}</dd></div></dl>{descriptor.available&&open?<button className="edx-button secondary" onClick={open}>{L("OPEN FEATURE","باز کردن قابلیت")} <Icon name="arrow"/></button>:<p>{descriptor.available?L("Live platform capability exposed through an EquiData surface or the native Control console.","قابلیت زنده پلتفرم از طریق سطح EquiData یا کنسول بومی کنترل ارائه می‌شود."):L("Not advertised by this backend. Preserved UI ideas remain disabled until a real contract/data source exists.","این سرویس آن را فعال اعلام نکرده است. ایده‌های رابط تا زمان وجود قرارداد و منبع داده واقعی غیرفعال می‌مانند.")}</p>}</article>})}</div></main>;
}


function EquiDataPremiumHorse({view,premium}:{view:EquiDataRuntime;premium:NonNullable<HorseInsightsResponse["premiumPedigree"]>}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);return <Panel className={`edx-premium-horse confidence-${premium.confidence.grade}`}><SectionTitle eyebrow={L("PREMIUM PEDIGREE INTELLIGENCE","تحلیل پیشرفته تبارنامه")} title={L("Diversity & concentration fingerprint","اثر انگشت تنوع و تمرکز")} copy={localizedAnalysisText(premium.provenance.interpretation,view.locale)}/><div className="edx-metrics-grid"><Metric label={L("Equivalent complete generations","نسل کامل معادل")} value={String(premium.equivalentCompleteGenerations)} tone="cyan"/><Metric label={L("Ancestor diversity","تنوع نیاکان")} value={pct(premium.ancestorDiversityPercent)} tone="green"/><Metric label={L("Weighted repetition burden","بار تکرار وزنی")} value={pct(premium.weightedRepeatedBurdenPercent)} tone="rose"/><Metric label={L("Top-5 path concentration","تمرکز ۵ مسیر برتر")} value={pct(premium.top5RecordedPathWeightSharePercent)} tone="gold"/><Metric label={L("Cross-branch repeats","تکرار بین دو شاخه")} value={num(premium.crossBranchRepeatedAncestorCount,view.locale)} tone="muted"/><Metric label={L("Confidence","اعتماد")} value={premium.confidence.grade.toUpperCase()} note={premium.confidence.reasons.join(" · ")} tone={premium.confidence.grade==="high"?"green":premium.confidence.grade==="medium"?"gold":"rose"}/></div><div className="edx-premium-ancestor-grid">{premium.topAncestorContributions.map(a=><button key={a.horse.id} onClick={()=>view.navigate(horseDbRoutes.horse(a.horse.id))}><strong dir="auto">{horseName(a.horse,view.locale)}</strong><span>{pct(a.shareOfRecordedPathWeightPercent)} · ×{num(a.occurrences,view.locale)} · G{num(a.nearestGeneration,view.locale)}</span></button>)}</div></Panel>}

function EquiDataReferenceHorse({view,reference}:{view:EquiDataRuntime;reference:NonNullable<HorseInsightsResponse["referencePopulation"]>}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const P=(v:number|null,d=1)=>v==null?"—":`${new Intl.NumberFormat(view.locale==="fa"?"fa-IR":"en-US",{maximumFractionDigits:d}).format(v)}%`;const mk=reference.meanKinship;return <Panel className={`edx-reference-horse confidence-${reference.confidence.grade}`}><SectionTitle eyebrow={L("REFERENCE POPULATION INTELLIGENCE","تحلیل جمعیت مرجع")} title={`${reference.cohort.label} · ${num(reference.cohort.startYear,view.locale)}–${num(reference.cohort.endYear,view.locale)}`} copy={localizedAnalysisText(reference.provenance.interpretation,view.locale)}/><p className="edx-reference-cohort">n={num(reference.cohort.populationSize,view.locale)} · sample {num(reference.cohort.sampleSize,view.locale)} · {reference.cohort.memberOfReferenceCohort?L("CURRENT COHORT MEMBER","عضو گروه مرجع جاری"):L("HISTORICAL / CONTEXT RECORD","رکورد تاریخی / زمینه‌ای")}</p><div className="edx-metrics-grid"><Metric label={L("Diversity preservation index","شاخص حفظ تنوع")} value={num(reference.diversityPreservationIndex.score,view.locale)} tone="green"/><Metric label={L("Mean kinship","میانگین خویشاوندی")} value={P(mk.estimatePercent,2)} note={mk.rarityPercentile==null?L("Outside current cohort; rarity context still available","خارج از گروه جاری؛ زمینه کمیابی همچنان موجود است"):`${L("rarity percentile","صدک کمیابی")} ${P(mk.rarityPercentile,0)}`} tone="cyan"/><Metric label={L("Ancestor rarity","کمیابی نیاکان")} value={P(reference.recordedAncestorRarity.index,1)} note={`${L("percentile","صدک")} ${P(reference.recordedAncestorRarity.percentile,0)}`} tone="gold"/><Metric label={L("Tail-male share","سهم خط پدری")} value={P(reference.directLines.tailMaleRootSharePercent,2)} tone="cyan"/><Metric label={L("Tail-female share","سهم خط مادری")} value={P(reference.directLines.tailFemaleRootSharePercent,2)} tone="rose"/><Metric label={L("Confidence","اعتماد")} value={reference.confidence.grade.toUpperCase()} note={reference.confidence.reasons.join(" · ")} tone={reference.confidence.grade==="high"?"green":reference.confidence.grade==="medium"?"gold":"rose"}/></div>{mk.approximate95PercentSamplingInterval&&<p className="edx-science-note">{L("Nominal 95% sampling interval","بازه اسمی ۹۵٪ نمونه‌گیری")}: {P(mk.approximate95PercentSamplingInterval[0],2)}–{P(mk.approximate95PercentSamplingInterval[1],2)} · SE {P(mk.standardErrorPercent,3)}</p>}<div className="edx-reference-components">{reference.diversityPreservationIndex.components.map(x=><span key={x.code} className={`component-${x.code}`}><small>{x.code}</small><b>{P(x.score,1)}</b><em>×{x.nominalWeight}</em></span>)}</div><details className="edx-reference-method"><summary>{L("Confidence & scientific method ledger","دفتر اعتماد و روش علمی")}</summary><div><span><small>{L("Mean-kinship percentile","صدک میانگین خویشاوندی")}</small><b>{P(mk.percentile,0)}</b></span><span className={`sampling-precision precision-${mk.samplingPrecision.grade}`}><small>{L("Sampling precision","دقت نمونه‌گیری")}</small><b>{mk.samplingPrecision.grade.toUpperCase()}</b><em>{mk.samplingPrecision.approximate95HalfWidthPercent==null?"—":`±${P(mk.samplingPrecision.approximate95HalfWidthPercent,2)}`}</em></span><span><small>{L("Pedigree completeness","کامل‌بودن تبارنامه")}</small><b>{P(reference.confidence.pedigreeCompletenessPercent,1)}</b></span><span><small>{L("Method","روش")}</small><b>{analysisMethodLabel(mk.method,view.locale)}</b></span><span><small>{L("Founder assumption","فرض بنیان‌گذار")}</small><b>{founderAssumptionLabel(mk.founderAssumption,view.locale)}</b></span><span><small>{L("Algorithm","الگوریتم")}</small><b>{reference.provenance.algorithmVersion}</b></span><span><small>{L("Source revision","ویرایش منبع")}</small><b>{reference.provenance.sourceRevision}</b></span></div><p className="edx-science-note">{localizedAnalysisText(mk.samplingPrecision.interpretation,view.locale)}</p><p className="edx-science-note">{localizedAnalysisText(reference.recordedAncestorRarity.interpretation,view.locale)}</p><p className="edx-science-note">{localizedAnalysisText(reference.diversityPreservationIndex.interpretation,view.locale)}</p></details></Panel>}

function EquiDataReferenceRegistry({view,rows}:{view:EquiDataRuntime;rows:NonNullable<NonNullable<RegistryAnalyticsResponse["premium"]>["referencePopulations"]>}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const P=(v:number|null)=>v==null?"—":pct(v);const N=(v:number|null)=>v==null?"—":num(v,view.locale);return <Panel className="edx-stat-card span-2 edx-reference-registry"><SectionTitle eyebrow={L("REFERENCE POPULATIONS","جمعیت‌های مرجع")} title={L("Same-breed cohort benchmarks","معیارهای گروه هم‌نژاد")} copy={rows[0]?.interpretation?localizedAnalysisText(rows[0].interpretation,view.locale):null}/><div className="edx-reference-table">{rows.map(row=><div key={row.key}><span><b dir="auto">{row.label}</b><small>{num(row.startYear,view.locale)}–{num(row.endYear,view.locale)} · n={num(row.populationSize,view.locale)} · sample {num(row.sampleSize,view.locale)}</small></span><span className="metric-kinship"><small>{L("Median mean kinship","میانه میانگین خویشاوندی")}</small><strong>{P(row.meanKinshipPercent.median)}</strong><em>{L("mean","میانگین")} {P(row.meanKinshipPercent.mean)} · P10–90 {P(row.meanKinshipPercent.p10)}–{P(row.meanKinshipPercent.p90)}</em></span><span className="metric-rarity"><small>{L("Ancestor rarity","کمیابی نیاکان")}</small><strong>{P(row.recordedAncestorRarityIndex.median)}</strong><em>{L("mean","میانگین")} {P(row.recordedAncestorRarityIndex.mean)} · P10–90 {P(row.recordedAncestorRarityIndex.p10)}–{P(row.recordedAncestorRarityIndex.p90)}</em></span><span className="metric-dpi"><small>{L("Median DPI","میانه شاخص حفظ تنوع")}</small><strong>{N(row.diversityPreservationIndex.median)}</strong><em>{L("mean","میانگین")} {N(row.diversityPreservationIndex.mean)} · P10–90 {N(row.diversityPreservationIndex.p10)}–{N(row.diversityPreservationIndex.p90)}</em></span><span className="metric-roots"><small>{L("Direct roots M/F","ریشه مستقیم پ/م")}</small><strong>{num(row.tailMaleDistinctRoots,view.locale)} / {num(row.tailFemaleDistinctRoots,view.locale)}</strong><em>{L("recorded direct-line roots","ریشه‌های ثبت‌شده خطوط مستقیم")}</em></span></div>)}</div></Panel>}
function EquiDataTrajectorySpark({values}:{values:Array<{decade:number;count:number}>}){const max=Math.max(1,...values.map(x=>x.count));return <div className="trajectory-spark" aria-hidden="true">{values.map(x=><i key={x.decade} style={{height:`${Math.max(8,(x.count/max)*100)}%`}} title={`${x.decade}: ${x.count}`}/>)}</div>}
function EquiDataInfluenceRegistry({view,data}:{view:EquiDataRuntime;data:NonNullable<NonNullable<RegistryAnalyticsResponse["premium"]>["influenceTrajectories"]>}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const group=(kind:"current"|"rising"|"fading",title:string,rows:typeof data.topCurrent)=><section className={`trajectory-${kind}`}><h4>{title}</h4><div>{rows.map(row=><button className={row.momentumPercent>0?"momentum-positive":row.momentumPercent<0?"momentum-negative":"momentum-flat"} key={`${title}-${row.horse.id}`} onClick={()=>view.navigate(horseDbRoutes.horse(row.horse.id))}><span dir="auto"><b>{horseName(row.horse,view.locale)}</b><small>#{num(row.horse.id,view.locale)} · {num(row.directChildren,view.locale)} {L("children","فرزند")} · {num(row.uniqueDescendantsDepth4,view.locale)} {L("G4 descendants","نواده G4")}</small></span><EquiDataTrajectorySpark values={row.byBirthDecade}/><span className="edx-trajectory-depth">{L("D4 positions","جایگاه D4")} <b>{num(row.representedAncestorPositionsDepth4,view.locale)}</b></span><strong>{num(row.recentDescendants,view.locale)}</strong><small>{L("prior","قبل")} {num(row.priorPeriodDescendants,view.locale)}</small><em>{row.momentumPercent>=0?"+":""}{num(row.momentumPercent,view.locale)}%</em></button>)}</div></section>;return <Panel className="edx-stat-card span-2 edx-influence-registry"><SectionTitle eyebrow={L("LINEAGE TRAJECTORIES","روند تبارها")} title={L("Recorded descendant reach & momentum","گستره و شتاب نوادگان ثبت‌شده")} copy={localizedAnalysisText(data.interpretation,view.locale)}/><div className="edx-influence-meta"><span>{L("Recent period","دوره اخیر")}: {data.recentPeriod[0]}–{data.recentPeriod[1]}</span><span>{L("Prior period","دوره قبل")}: {data.priorPeriod[0]}–{data.priorPeriod[1]}</span><span>{L("Depth","عمق")}: G{num(data.depth,view.locale)}</span></div><div className="edx-influence-groups">{group("current",L("Strongest recent reach","بیشترین گستره اخیر"),data.topCurrent)}{group("rising",L("Rising lines","خطوط رو به رشد"),data.rising)}{group("fading",L("Fading lines","خطوط رو به کاهش"),data.fading)}</div></Panel>}

function EquiDataPremiumRegistry({view,analytics}:{view:EquiDataRuntime;analytics:RegistryAnalyticsResponse}){const L=(en:string,fa:string)=>edxText(view.locale,en,fa);const p=analytics.premium;if(!p)return <EmptyPanel title={L("Premium analytics unavailable","تحلیل ممتاز در دسترس نیست")} copy={L("Rebuild the current analytics snapshot with algorithm 2.x.","تصویر آماری را با الگوریتم ۲.x بازسازی کنید.")}/>;const conc=(label:string,x:typeof p.parentConcentration.sires)=><Panel className="edx-stat-card"><h3>{label}</h3><div className="edx-metrics-grid compact"><Metric label={L("Assignments","انتساب")} value={num(x.assignments,view.locale)} tone="muted"/><Metric label={L("Distinct parents","والد یکتا")} value={num(x.distinctParents,view.locale)} tone="cyan"/><Metric label={L("Top 1 / 5 / 10","سهم ۱ / ۵ / ۱۰")} value={`${pct(x.top1SharePercent)} / ${pct(x.top5SharePercent)} / ${pct(x.top10SharePercent)}`} tone="gold"/><Metric label="HHI" value={String(x.hhi)} tone="rose"/><Metric label={L("Gini / Shannon","جینی / شانون")} value={`${x.gini} / ${x.shannonEntropy}`} tone="gold"/><Metric label={L("Effective entropy / Simpson","مؤثر انتروپی / سیمپسون")} value={`${num(Math.round(x.entropyEffectiveParentCount),view.locale)} / ${num(Math.round(x.inverseSimpsonEffectiveParentCount),view.locale)}`} tone="green"/></div></Panel>;const gi=p.generationIntervals;const interval=(label:string,x:typeof gi.sireToOffspring)=><span><b>{x.medianYears==null?"—":`${x.medianYears} ${L("yr","سال")}`}</b><small>{label} · {L("mean","میانگین")} {x.meanYears??"—"} · P10–P90 {x.p10Years??"—"}–{x.p90Years??"—"} · N {num(x.count,view.locale)}</small></span>;return <div className="edx-observatory-grid two"><Panel className="edx-stat-card span-2"><SectionTitle eyebrow={L("ANALYTICAL TRUST LAYER","لایه اعتماد تحلیلی")} title={L("Eligibility before interpretation","اعتبارسنجی پیش از تفسیر")} copy={L("Premium statistics explicitly exclude documented sentinel and cycle-contaminated cases where relevant.","آمار ممتاز در موارد مرتبط، مقادیر نگهبان و تبارهای آلوده به چرخه را به‌طور صریح حذف می‌کند.")}/><div className="edx-metrics-grid compact"><Metric label={L("Birth-year eligible","سال تولد قابل تحلیل")} value={pct(p.analyticalValidity.birthYear.coveragePercent)} note={`${num(p.analyticalValidity.birthYear.eligibleRecords,view.locale)} / ${num(p.analyticalValidity.birthYear.totalRecords,view.locale)}`} tone="green"/><Metric label={L("Pedigree eligible","تبار قابل تحلیل")} value={pct(p.analyticalValidity.pedigree.coveragePercent)} note={`${num(p.analyticalValidity.pedigree.eligibleRecords,view.locale)} / ${num(p.analyticalValidity.pedigree.totalRecords,view.locale)}`} tone="cyan"/><Metric label={L("Parent-year conflicts","تعارض سال والد")} value={num(p.analyticalValidity.parentYearConflictCount,view.locale)} tone="rose"/><Metric label={L("Cycle issues","مسائل چرخه")} value={num(p.analyticalValidity.cycleIssueCount,view.locale)} tone="rose"/><Metric label={L("Meaningful DNA records","رکوردهای معنادار DNA")} value={num(p.analyticalValidity.meaningfulDnaRecords,view.locale)} note={L("coverage only","فقط پوشش")} tone="gold"/><Metric label={L("Median / avg ECG","میانه / میانگین ECG")} value={`${p.pedigreeDiversity?.medianEquivalentCompleteGenerations??0} / ${p.pedigreeDiversity?.averageEquivalentCompleteGenerations??0}`} note={p.pedigreeDiversity?`${num(p.pedigreeDiversity.eligibleHorseCount,view.locale)} · G${num(p.pedigreeDiversity.depth,view.locale)}`:undefined} tone="muted"/></div>{p.analyticalValidity.birthYear.exclusions.map(x=><p className="edx-science-note" key={x.code}><b>{x.code}</b> · {num(x.count,view.locale)} · {localizedAnalysisText(x.interpretation,view.locale)}</p>)}</Panel>{conc(L("Sire concentration","تمرکز پدران"),p.parentConcentration.sires)}{conc(L("Dam concentration","تمرکز مادران"),p.parentConcentration.dams)}{p.peopleConcentration&&<Panel className="edx-stat-card span-2"><h3>{L("Registry people-link concentration","تمرکز پیوند افراد سامانه ثبت")}</h3><div className="edx-metrics-grid compact">{[[L("Owners","مالکان"),p.peopleConcentration.owners],[L("Breeders","پرورش‌دهندگان"),p.peopleConcentration.breeders],[L("Importers","واردکنندگان"),p.peopleConcentration.importers],[L("Passport receivers","گیرندگان گذرنامه"),p.peopleConcentration.passportReceivers]].map(([label,x]:any)=><Metric key={label} label={label} value={`${num(x.distinctPeople,view.locale)} · T10 ${pct(x.top10SharePercent)}`} note={`T1/T5 ${pct(x.top1SharePercent)}/${pct(x.top5SharePercent)} · HHI ${x.hhi} · G ${x.gini} · H ${x.shannonEntropy} · E ${num(Math.round(x.entropyEffectivePeopleCount),view.locale)} · S ${num(Math.round(x.inverseSimpsonEffectivePeopleCount),view.locale)}`} tone="cyan"/>)}</div><p className="edx-science-note">{localizedAnalysisText(p.peopleConcentration.interpretation,view.locale)}</p></Panel>}<Panel className="edx-stat-card span-2"><h3>{L("Generation intervals","فاصله‌های نسلی")}</h3><p className="edx-science-note">{L("Plausible analytical age range","بازه سنی تحلیلی معتبر")}: {gi.plausibleAgeRangeYears[0]}–{gi.plausibleAgeRangeYears[1]} {L("years","سال")}</p><div className="edx-interval-grid">{interval(L("Sire → offspring","پدر ← فرزند"),gi.sireToOffspring)}{interval(L("Dam → offspring","مادر ← فرزند"),gi.damToOffspring)}{interval(L("Sire → son","پدر ← پسر"),gi.sireToSon)}{interval(L("Sire → daughter","پدر ← دختر"),gi.sireToDaughter)}{interval(L("Dam → son","مادر ← پسر"),gi.damToSon)}{interval(L("Dam → daughter","مادر ← دختر"),gi.damToDaughter)}</div><details className="edx-interval-history"><summary>{L("Generation intervals by offspring birth decade","فاصله نسلی بر حسب دهه تولد فرزند")}</summary><div>{gi.byOffspringBirthDecade.map(x=><span key={x.decade}><b>{num(x.decade,view.locale)}</b><small>S→O {x.sire.medianYears??"—"} · D→O {x.dam.medianYears??"—"}</small></span>)}</div></details></Panel>{p.lineSurvival&&<Panel className="edx-stat-card span-2"><h3>{L("Direct-line survival","بقای خطوط مستقیم")}</h3><p className="edx-science-note">{`${p.lineSurvival.cohort.startYear}–${p.lineSurvival.cohort.endYear}`} · {num(p.lineSurvival.cohort.horses,view.locale)} · {p.lineSurvival.cohort.startYear}–{p.lineSurvival.cohort.endYear}</p><div className="edx-metrics-grid compact"><Metric label={L("Tail-male roots","ریشه خط پدری")} value={num(p.lineSurvival.tailMale.distinctRecordedRoots,view.locale)} note={`${L("Top 10 share","سهم ۱۰ برتر")} ${pct(p.lineSurvival.tailMale.top10SharePercent)}`} tone="cyan"/><Metric label={L("Tail-female roots","ریشه خط مادری")} value={num(p.lineSurvival.tailFemale.distinctRecordedRoots,view.locale)} note={`${L("Top 10 share","سهم ۱۰ برتر")} ${pct(p.lineSurvival.tailFemale.top10SharePercent)}`} tone="rose"/></div><div className="edx-premium-root-columns"><section><h4>{L("Top tail-male roots","ریشه‌های برتر خط پدری")}</h4><div className="edx-premium-ancestor-grid">{p.lineSurvival.tailMale.topRoots.map(r=><button key={`m-${r.id}`} onClick={()=>view.navigate(horseDbRoutes.horse(r.id))}><strong dir="auto">{view.locale==="fa"?(r.name_native||r.name_latin):(r.name_latin||r.name_native)}</strong><span>{num(r.count,view.locale)}</span></button>)}</div></section><section><h4>{L("Top tail-female roots","ریشه‌های برتر خط مادری")}</h4><div className="edx-premium-ancestor-grid">{p.lineSurvival.tailFemale.topRoots.map(r=><button key={`f-${r.id}`} onClick={()=>view.navigate(horseDbRoutes.horse(r.id))}><strong dir="auto">{view.locale==="fa"?(r.name_native||r.name_latin):(r.name_latin||r.name_native)}</strong><span>{num(r.count,view.locale)}</span></button>)}</div></section></div><p className="edx-science-note">{localizedAnalysisText(p.lineSurvival.interpretation,view.locale)}</p></Panel>}{p.referencePopulations?.length?<EquiDataReferenceRegistry view={view} rows={p.referencePopulations}/>:null}{p.influenceTrajectories?<EquiDataInfluenceRegistry view={view} data={p.influenceTrajectories}/>:null}<Panel className="edx-stat-card span-2"><h3>{L("Concentration history by birth decade","تاریخچه تمرکز بر حسب دهه تولد")}</h3>{p.parentConcentration.recentCohort&&<p className="edx-science-note">{`${p.parentConcentration.recentCohort.startYear}–${p.parentConcentration.recentCohort.endYear}`} · {p.parentConcentration.recentCohort.startYear}–{p.parentConcentration.recentCohort.endYear} · {num(p.parentConcentration.recentCohort.horses,view.locale)} {L("horses","اسب")} · S T10 {pct(p.parentConcentration.recentCohort.sires.top10SharePercent)} · D T10 {pct(p.parentConcentration.recentCohort.dams.top10SharePercent)}</p>}<div className="edx-premium-decades">{p.parentConcentration.byBirthDecade.map(x=><span key={x.decade}><b>{num(x.decade,view.locale)}</b><small>N {num(x.horses,view.locale)}</small><small>{L("sire top10","۱۰ پدر")} {pct(x.sires.top10SharePercent)}</small><small>HHI {x.sires.hhi}</small><small>{L("dam top10","۱۰ مادر")} {pct(x.dams.top10SharePercent)}</small></span>)}</div></Panel></div>}

